export type ArticleSection = { heading: string; paragraphs: string[]; examples?: string[]; bullets?: string[]; links?: { label: string; url: string }[] };
export type Article = { slug: string; category: string; title: string; excerpt: string; time: string; icon: string; keywords?: string[]; body: string[]; sections?: ArticleSection[] };

const section = (heading: string, paragraphs: string[], examples?: string[], bullets?: string[], links?: { label: string; url: string }[]): ArticleSection => ({ heading, paragraphs, ...(examples ? { examples } : {}), ...(bullets ? { bullets } : {}), ...(links ? { links } : {}) });
const article = (slug: string, category: string, title: string, excerpt: string, icon: string, keywords: string[], intro: string, sections: ArticleSection[], time = "6 min"): Article => ({ slug, category, title, excerpt, time, icon, keywords, body: [intro], sections });

const articleDrafts: Article[] = [
  { slug: "praticar-o-th", category: "Pronúncia", title: "Como praticar o ‘th’ sem travar", excerpt: "Um exercício curto para perceber o som e treinar no seu ritmo.", time: "4 min", icon: "◉", keywords: ["pronúncia th", "think", "this", "inglês para brasileiros"], body: ["O som ‘th’ aparece em palavras como ‘think’ e ‘this’. Ele não tem um equivalente exato em português, então vale observar a posição da língua: toque levemente a ponta entre os dentes e deixe o ar passar.", "Comece devagar. Diga ‘think’, faça uma pausa, e repita. Depois compare com ‘this’. O primeiro costuma ser sem vibração; o segundo, com a voz vibrando.", "A leitura de voz pode ajudar a ouvir um modelo, mas não avalia a sua pronúncia. Grave a si mesmo apenas se quiser, usando ferramentas do seu próprio dispositivo."] },
  { slug: "rotina-15-minutos", category: "Rotina de estudos", title: "15 minutos de inglês que cabem no dia", excerpt: "Uma sequência simples de leitura, escuta e recuperação ativa.", time: "6 min", icon: "↗", keywords: ["rotina de inglês", "estudar inglês todos os dias", "15 minutos"], body: ["Uma rotina pequena e repetível costuma ser mais fácil de manter do que um plano perfeito. Separe cinco minutos para ler algo curto, cinco para ouvir, e cinco para tentar recuperar as palavras sem olhar.", "Escolha um único objetivo para cada sessão: aprender três expressões, entender uma ideia central ou contar o que aconteceu em um texto.", "Se um dia não der certo, retome no seguinte. Progresso não precisa ser uma sequência sem falhas."] },

  article("como-dizer-horas-em-ingles", "Vocabulário cotidiano", "Como dizer as horas em inglês? Guia completo com exemplos", "Aprenda a perguntar e informar horários em inglês: a forma digital, o sistema com past e to, a.m. e p.m., o relógio de 24 horas e expressões do dia a dia.", "◷", ["horas em inglês", "como dizer as horas em inglês", "que horas são em inglês", "what time is it", "past to horas inglês", "am pm inglês horas"], "Dizer as horas é uma das primeiras coisas úteis que você aprende em inglês — aparece em conversas, compromissos, viagens e provas. Há dois sistemas: a forma digital (hora + minutos), mais simples e cada vez mais comum, e o sistema tradicional com past e to. Neste guia você aprende os dois, como usar a.m. e p.m., como perguntar as horas e as expressões de rotina que mais aparecem.", [
    section("A forma digital: simples e natural", ["O jeito mais fácil é dizer a hora e depois os minutos, como num relógio digital. It’s seven fifteen (7:15), it’s nine thirty (9:30). Para horas ‘cheias’, use o’clock: it’s three o’clock (3:00) — o’clock só se usa com a hora exata.", "Para minutos de 1 a 9, acrescente oh (a letra O) antes do número: 7:05 é seven oh five. Essa forma funciona em qualquer situação e é a preferida por muitos falantes."], ["It’s 7:15. — It’s seven fifteen. — São 7h15.", "It’s 9:30. — It’s nine thirty. — São 9h30.", "It’s 8:05. — It’s eight oh five. — São 8h05.", "It’s 6:00. — It’s six o’clock. — São 6h em ponto."]),
    section("O sistema com past e to", ["O sistema tradicional divide o relógio em duas metades. Até a meia hora, use past (minutos depois da hora): ten past three (3:10). Depois da meia hora, use to (minutos que faltam para a próxima hora): twenty to four (3:40).", "Nesse sistema há palavras especiais: a quarter para 15 minutos, half para 30 minutos. Então 3:15 é a quarter past three, 3:30 é half past three e 3:45 é a quarter to four."], ["It’s quarter past three. — São 3h15.", "It’s half past three. — São 3h30.", "It’s quarter to four. — São 3h45.", "It’s ten to six. — São 5h50."]),
    section("a.m., p.m. e o relógio de 24 horas", ["O inglês do dia a dia usa o relógio de 12 horas com a.m. (madrugada e manhã, 0h–11h59) e p.m. (tarde e noite, 12h–23h59). Assim, 9 a.m. é 9h da manhã e 9 p.m. é 21h.", "O relógio de 24 horas (fourteen hundred para 14:00) existe, mas é mais restrito a contextos militares, aeroportos e horários oficiais. Na conversa comum, prefira a.m./p.m. ou expressões como in the morning, in the afternoon, in the evening e at night."], ["The class starts at 9:30 a.m. — A aula começa às 9h30 da manhã.", "The movie is at 8 p.m. — O filme é às 20h.", "I wake up at six in the morning. — Acordo às seis da manhã."]),
    section("Como perguntar e responder as horas", ["A pergunta mais comum é What time is it? (Que horas são?) ou, de forma mais educada, Could you tell me the time, please? Para perguntar o horário de um evento, use What time…? com o verbo: What time does it start?", "Para responder com um horário de evento ou rotina, use a preposição at: at two o’clock, at noon (meio-dia), at midnight (meia-noite)."], ["What time is it? — Que horas são?", "What time does the meeting start? — A que horas começa a reunião?", "It’s at two o’clock. — É às duas horas.", "Do you have the time? — Você tem horas?"]),
    section("Expressões úteis sobre horários", ["Vale aprender alguns termos que aparecem muito: noon (meio-dia), midnight (meia-noite), midday, in the morning/afternoon/evening, at night. E expressões aproximadas: about five / around five (por volta das cinco), sharp (em ponto): at nine sharp.", "Para falar de pontualidade, lembre: on time (na hora marcada) e in time (a tempo, com folga)."], ["It’s noon. — É meio-dia.", "Let’s meet at around seven. — Vamos nos encontrar por volta das sete.", "The train leaves at 8 o’clock sharp. — O trem sai às 8 em ponto."]),
    section("Perguntas frequentes sobre as horas", ["É ‘o’clock’ em qualquer horário? Não — só com horas cheias (five o’clock), nunca com minutos. Preciso usar past e to? Não; a forma digital (five forty) é aceita e simples. É ‘half past three’ ou ‘three and a half’? Em inglês, half past three — nunca a tradução literal do português. Como escrevo 12h? Use noon ou 12 p.m. para meio-dia e midnight ou 12 a.m. para meia-noite."]),
    section("Continue praticando", ["Horários aparecem junto com as preposições de tempo (at, in, on) e com a rotina diária — temas das primeiras aulas do curso. Pratique dizendo a que horas você faz cada coisa no seu dia."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: in, on e at para tempo e lugar",url:"/blog/in-on-at-tempo-lugar"},{label:"Como marcar um horário por telefone em inglês",url:"/blog/marcar-consulta-por-telefone-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("say-tell-speak-talk-diferenca", "Vocabulário e uso", "Say, tell, speak e talk: qual é a diferença e como usar cada um?", "Quatro verbos, duas traduções (‘dizer’ e ‘falar’) e estruturas diferentes. Veja a regra prática, exemplos, expressões fixas e os erros que mais confundem.", "Aa", ["say tell speak talk diferença", "verbos falar inglês", "como usar say e tell", "diferença say tell", "speak ou talk", "say tell speak talk exemplos"], "Say, tell, speak e talk traduzem ‘dizer’ ou ‘falar’, mas o inglês escolhe cada um conforme a estrutura da frase, não o significado isolado. A chave é lembrar o que costuma vir depois de cada verbo: say foca no conteúdo, tell exige a pessoa que recebe a informação, e speak e talk descrevem o ato de conversar. Neste guia você vê a regra prática com muitos exemplos e os deslizes mais comuns de brasileiros.", [
    section("A regra prática em uma frase", ["Para não travar na hora de falar, guarde este resumo: você say something (diz algo), tell someone something (conta algo a alguém), e speak/talk about something (fala sobre algo, conversa). A diferença mais útil é entre say e tell.", "Say costuma vir direto com o que foi dito. Tell quase sempre precisa da pessoa logo depois: tell me, tell him, tell us. Já speak e talk são verbos de conversa, geralmente com to ou about."], undefined, ["say + algo dito: say something (to someone)", "tell + pessoa + algo: tell someone something", "speak / talk + to/about: speak to someone, talk about something"]),
    section("Say: o foco está no conteúdo", ["Say destaca as palavras ditas. Se você quiser mencionar quem ouviu, precisa da preposição to: say something to someone — nunca say me.", "Say também aparece em discurso indireto e em frases muito comuns do dia a dia."], ["She said hello. — Ela disse olá.", "He said (that) he was tired. — Ele disse que estava cansado.", "Can you say that again? — Pode repetir isso?", "say me ✗ → say to me ✓"]),
    section("Tell: informação dirigida a alguém", ["Tell normalmente vem seguido da pessoa que recebe a informação, sem preposição: tell me, tell her, tell them. Por isso é o verbo de instruções e informações diretas.", "Tell também forma várias expressões fixas que vale memorizar: tell a story, tell the truth, tell a lie, tell the time, tell the difference."], ["Tell me your name. — Diga-me seu nome.", "They told us a story. — Eles nos contaram uma história.", "Always tell the truth. — Sempre diga a verdade.", "tell to me ✗ → tell me ✓"]),
    section("Speak e talk: falar e conversar", ["Speak e talk descrevem o ato de falar. São muito próximos, mas speak pode soar um pouco mais formal e aparece com idiomas (speak English) e em situações de fala formal (speak to a manager). Talk é mais associado a conversa informal.", "Os dois usam to someone (ou with someone) e about something. Em muitos contextos são intercambiáveis: I need to speak/talk to you."], ["Do you speak English? — Você fala inglês?", "I talked to my friend for an hour. — Conversei com meu amigo por uma hora.", "Can I speak to the manager? — Posso falar com o gerente?", "We talked about the trip. — Conversamos sobre a viagem."]),
    section("Erros comuns com esses verbos", ["O erro mais comum é usar tell sem a pessoa (tell a word to the group ✗) ou say com a pessoa direta (he said me ✗). Também é frequente traduzir “falar inglês” como talk English, quando o natural é speak English.", "Para fixar, repita mini-frases trocando os verbos: say hello, tell me a secret, speak slowly, talk about music. A estrutura certa entra com repetição."], ["He said me the news. ✗ → He told me the news. ✓", "I want to tell something. ✗ → I want to tell you something. ✓", "I talk English. ✗ → I speak English. ✓"]),
    section("Perguntas frequentes", ["É “say to me” ou “tell me”? Ambos existem, mas com estruturas diferentes: say something to me ou tell me something. Qual uso para idiomas? Speak: she speaks three languages. Speak e talk são iguais? Quase: talk tende ao informal e à conversa; speak, ao formal e ao ato de falar. Na dúvida entre os dois, qualquer um costuma funcionar."]),
    section("Continue praticando", ["Esses quatro verbos aparecem o tempo todo em conversas e provas. As aulas do curso os apresentam em diálogos, e vale combinar este tema com o estudo de perguntas e de como se apresentar em inglês."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como se apresentar em inglês",url:"/blog/frases-para-se-apresentar-em-ingles"},{label:"Veja também: do ou make",url:"/blog/do-ou-make-em-ingles"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("do-ou-make-em-ingles", "Vocabulário e uso", "Do ou make em inglês: qual é a diferença e quando usar cada um?", "Do e make traduzem ‘fazer’, mas não são intercambiáveis. Veja a lógica por trás dos dois, as combinações mais comuns, listas prontas e os erros que mais confundem brasileiros.", "Do/Make", ["do ou make", "diferença do make", "do ou make em inglês", "quando usar do e make", "collocations do make", "do make inglês exemplos"], "Do e make são um clássico problema de quem aprende inglês: os dois significam ‘fazer’ em português, mas o inglês escolhe um ou outro conforme a palavra que vem junto. A escolha não é aleatória — existe uma tendência geral — mas o caminho mais seguro é aprender as combinações (collocations) como blocos prontos. Neste guia você vê a lógica, as listas mais úteis e os deslizes mais frequentes.", [
    section("A diferença geral entre do e make", ["Como regra de bolso: do costuma aparecer com tarefas, obrigações e atividades gerais, muitas vezes sem resultado concreto visível. Make costuma aparecer quando você cria, produz ou causa algo — algo que passa a existir depois da ação.", "Pense assim: você do an activity (realiza uma atividade), mas make a product (produz um resultado). Essa imagem resolve muitos casos, mas não todos — por isso as listas abaixo são tão úteis quanto a regra."], undefined, ["do → tarefa, atividade, obrigação (foco no processo)", "make → criar, produzir, causar (foco no resultado)"]),
    section("Combinações comuns com DO", ["Do aparece em tarefas do dia a dia, trabalho, estudo e atividades físicas. Também é o verbo das tarefas domésticas em geral e de expressões vagas como do something ou do nothing.", "Guarde estas combinações como blocos — elas cobrem boa parte do uso cotidiano de do."], ["do homework / do the housework — fazer a lição / as tarefas de casa", "do the dishes / do the laundry — lavar a louça / a roupa", "do exercise / do yoga / do your best — fazer exercício / yoga / o seu melhor", "do a course / do business / do research — fazer um curso / negócios / pesquisa"]),
    section("Combinações comuns com MAKE", ["Make aparece quando algo é criado ou preparado — comida, planos, decisões — e em muitas expressões sobre comunicação e relações.", "Note que erros e barulho levam make: make a mistake, make noise. E decisões, planos e progresso também: make a decision, make plans, make progress."], ["make breakfast / make a cake / make coffee — preparar o café / um bolo / café", "make a decision / make a plan / make an appointment — tomar uma decisão / fazer um plano / marcar um horário", "make a mistake / make noise / make a mess — cometer um erro / fazer barulho / bagunça", "make friends / make money / make progress — fazer amigos / ganhar dinheiro / progredir"]),
    section("Erros comuns com do e make", ["O erro mais frequente é traduzir direto do português e escolher o verbo errado. “Fazer um erro” vira make a mistake, não do a mistake. “Fazer uma pergunta” não é make a question nem do a question, e sim ask a question. “Fazer uma festa” costuma ser have a party ou throw a party.", "Por isso, desconfie da tradução literal: muitas vezes o inglês nem usa do nem make. Quando surgir a dúvida, procure a collocation real em um dicionário de inglês e anote a frase inteira."], ["do a mistake ✗ → make a mistake ✓", "make a question ✗ → ask a question ✓", "do a party ✗ → have a party ✓", "make homework ✗ → do homework ✓"]),
    section("Como memorizar as collocations", ["Decorar listas soltas funciona pouco. O que fixa é encontrar a expressão em uma frase, repetir em contextos diferentes e produzir a sua própria frase. Escolha cinco combinações por semana e use cada uma em algo real da sua rotina.", "Um bom exercício é descrever o seu dia alternando os dois verbos: o que você do (tarefas) e o que você make (resultados)."], ["Every morning I make breakfast and do the dishes. — Toda manhã preparo o café e lavo a louça.", "I need to make a decision and do my homework today. — Preciso tomar uma decisão e fazer minha lição hoje."]),
    section("Perguntas frequentes sobre do e make", ["Existe uma regra que resolve todos os casos? Não. A tendência (do = atividade, make = criar) ajuda, mas há combinações fixas que você aprende pelo uso. É “do a favor” ou “make a favor”? É do someone a favor. É “make a shower”? Não — é have a shower ou take a shower.", "Quanto mais você ler e ouvir inglês, mais essas duplas entram no automático. Não tente deduzir cada uma: colecione as que aparecem com mais frequência."]),
    section("Continue ampliando o vocabulário", ["As collocations são a base de um inglês natural. As aulas do curso apresentam do e make em situações cotidianas, e vale combinar este tema com o estudo de como aprender e fixar vocabulário novo."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como aprender vocabulário e lembrar das palavras",url:"/blog/como-aprender-vocabulario-ingles"},{label:"Veja também: say, tell, speak e talk",url:"/blog/say-tell-speak-talk-diferenca"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("in-on-at-tempo-lugar", "Gramática essencial", "Quando usar in, on e at para tempo e lugar?", "Um guia completo para escolher entre in, on e at em horários, datas e lugares, com exemplos, erros comuns e expressões fixas.", "⌖", ["in on at", "preposições inglês", "in on at tempo", "in on at lugar", "quando usar in on at", "preposições de tempo e lugar inglês"], "In, on e at estão entre as preposições mais usadas — e mais confundidas — do inglês. A boa notícia é que existe uma lógica de escala que resolve a maioria dos casos: pense em in para o que é amplo ou fechado, on para superfícies e dias, e at para pontos específicos. Neste guia você vai ver essa lógica aplicada a tempo e a lugar, os erros mais comuns de quem fala português e as expressões fixas que vale memorizar de uma vez.", [
    section("A lógica das três preposições", ["Antes de decorar listas, vale entender a imagem por trás de cada preposição. Pense em um zoom: in é a visão mais ampla ou algo que envolve por todos os lados; on é uma superfície ou uma linha; at é um ponto preciso no mapa ou no relógio.", "Essa mesma lógica vale para tempo e para lugar, o que facilita a memória. Um ano (in 2026) é um período longo; um dia (on Monday) é um ponto numa linha de dias; uma hora (at 7 o’clock) é um instante exato. Quando tiver dúvida, pergunte-se: isto é amplo, uma superfície ou um ponto?"], undefined, ["in → amplo ou fechado: in Brazil, in 2026, in the box", "on → superfície ou dia: on the table, on Monday, on the wall", "at → ponto exato: at home, at 8 o’clock, at the door"]),
    section("In, on e at para falar de tempo", ["Use in com períodos longos: meses, estações, anos, décadas, séculos e partes do dia. Use on com dias e datas específicas. Use at com horários exatos e alguns momentos pontuais.", "Repare que partes do dia levam in (in the morning, in the afternoon, in the evening), mas night é a exceção clássica: diz-se at night. Datas completas combinam on com o dia: on July 4th."], ["in July / in 2026 / in the winter / in the morning", "on Monday / on July 4th / on my birthday / on the weekend (EUA)", "at 8:30 / at noon / at night / at Christmas (o período)"], ["Períodos longos e partes do dia: in", "Dias e datas: on", "Horas e pontos no tempo: at"]),
    section("In, on e at para falar de lugar", ["Para lugar, use in com espaços fechados ou áreas amplas (países, cidades, cômodos, veículos onde você entra). Use on com superfícies, linhas e meios de transporte públicos. Use at com pontos específicos, endereços e eventos.", "A diferença entre in e at aparece bem com lugares: in London fala da cidade como área; at the station fala do ponto exato onde você está. Com transporte, note o contraste: in a car ou in a taxi, mas on a bus, on a train e on a plane."], ["in the kitchen / in Brazil / in a taxi", "on the table / on the second floor / on the bus", "at the bus stop / at the door / at a concert"]),
    section("Os erros mais comuns de quem fala português", ["Alguns usos não têm tradução direta e geram erro. Em português dizemos “na rua”, mas em inglês o comum é on the street (ou in the street em inglês britânico, com leve diferença de sentido). “Chegar” também confunde: usa-se arrive in com cidades e países e arrive at com lugares específicos, nunca arrive to.", "Outro ponto é o fim de semana: at the weekend no inglês britânico e on the weekend no americano. E cuidado com in time (a tempo, com folga) versus on time (pontualmente, na hora marcada)."], ["arrive in Brazil / arrive at the airport (não “arrive to”)", "on the street (EUA) — na rua", "We got there just in time. — Chegamos bem a tempo.", "The train left on time. — O trem saiu no horário."]),
    section("Expressões fixas que vale memorizar", ["Algumas combinações são convencionais e é mais rápido guardá-las como blocos do que aplicar a regra. Muitas ligam at a lugares do cotidiano sem artigo.", "Anote cada expressão junto de uma frase sua — assim você aprende o uso, não só a tradução da preposição isolada."], ["at home / at work / at school / at university", "in bed / in hospital / in prison", "on TV / on the radio / on the phone / on the internet", "in the end (enfim) / at the end (no final de algo)"]),
    section("Perguntas frequentes sobre in, on e at", ["É at night ou in the night? No uso geral, diz-se at night (I don’t work at night). In the night aparece em contextos mais específicos ou literários. É on ou in com dias? Dias levam on: on Friday, on my day off. É arrive in ou arrive at? Use arrive in para cidades e países e arrive at para pontos como aeroporto, estação ou escritório.", "Essas preposições só entram na memória com repetição em contexto. Faça frases sobre a sua própria rotina — a que horas você acorda (at), em que dias estuda (on) e em que meses viaja (in)."]),
    section("Continue praticando preposições", ["O jeito mais eficiente de fixar in, on e at é ver as três em frases reais e tentar produzir as suas. As aulas iniciais do curso trazem horários, dias e lugares exatamente nesses contextos, e os simulados cobram preposições em questões de uso."], undefined, undefined, [{label:"Comece pelas aulas de inglês do nível A1",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Veja também: como dizer as horas em inglês",url:"/blog/como-dizer-horas-em-ingles"},{label:"Treine com os simulados de inglês grátis",url:"/simulados"}]),
  ], "9 min"),
  article("simple-present-vs-present-continuous", "Gramática essencial", "Simple present ou present continuous: qual usar e quando?", "Compare o presente simples e o presente contínuo em inglês: hábitos e fatos contra ações de agora, com formas, marcadores de tempo, verbos de estado e erros comuns.", "↔", ["simple present present continuous", "presente simples contínuo", "diferença simple present present continuous", "quando usar present continuous", "ing presente inglês", "verbos de estado inglês"], "O simple present e o present continuous são os dois tempos do presente em inglês, e a dúvida entre eles é constante no começo. A diferença é de foco: o simple present fala de hábitos, rotinas e fatos gerais — coisas verdadeiras em geral; o present continuous fala do que está acontecendo agora ou de situações temporárias. Neste guia você vê as formas, os marcadores de tempo que ajudam a escolher e uma pegadinha importante: os verbos de estado.", [
    section("A diferença em uma frase", ["Use o simple present para o que é habitual ou permanente: I work in a bank (sempre), water boils at 100°C (fato). Use o present continuous para o que está em andamento agora ou nestes dias: I’m working from home this week (temporário).", "A mesma pessoa pode dizer as duas coisas: He works at a café (é o emprego dele) e He’s working late tonight (ação de hoje). O verbo é o mesmo; o tempo muda o sentido."], undefined, ["simple present → hábito, rotina, fato geral", "present continuous → ação agora, situação temporária"]),
    section("Como formar cada tempo", ["O simple present usa o verbo na forma base, acrescentando -s na terceira pessoa (he/she/it): I work, she works. Nas perguntas e negativas, use do/does: Do you work? She doesn’t work.", "O present continuous usa to be (am/is/are) + verbo com -ing: I am working, they are working. A pergunta inverte o be: Are you working? A negativa acrescenta not: She isn’t working."], ["I work / she works / they work", "Do you work here? / She doesn’t work on Sundays.", "I’m studying now. / Are you studying? / He isn’t studying."]),
    section("Marcadores de tempo que ajudam", ["Certas palavras denunciam o tempo certo. O simple present combina com always, usually, often, sometimes, never, every day, on Mondays. O present continuous combina com now, right now, at the moment, today, this week, currently.", "Esses marcadores são pistas úteis, mas não substituem o sentido da frase — o que decide é se a ação é habitual ou está em andamento."], ["I usually get up at seven. — Normalmente acordo às sete.", "Look! It’s raining right now. — Olha! Está chovendo agora.", "She’s learning French this year. — Ela está aprendendo francês este ano."]),
    section("A pegadinha: verbos de estado", ["Alguns verbos normalmente não entram no present continuous, mesmo falando do agora. São os verbos de estado (stative verbs): like, love, hate, want, need, know, understand, believe, remember, seem, e os sentidos como see, hear. Com eles, use o simple present.", "Por isso dizemos I understand (não I’m understanding) e I want coffee (não I’m wanting). O caso famoso de propaganda I’m lovin’ it é informal e proposital — o padrão é I love it."], ["I want a coffee. — Quero um café. (não ‘I’m wanting’)", "She knows the answer. — Ela sabe a resposta. (não ‘is knowing’)", "I don’t understand. — Não entendo. (não ‘I’m not understanding’)"]),
    section("Erros comuns de brasileiros", ["O erro mais frequente é esquecer o -s da terceira pessoa no simple present: She work ✗ → She works ✓. Outro é usar o present continuous para hábitos, por influência do gerúndio português: ‘Eu estou trabalhando todo dia’ não é I’m working every day, e sim I work every day.", "Também é comum colocar verbos de estado no -ing (I’m knowing ✗). Para fixar, descreva a sua rotina (simple present) e depois o que você está fazendo neste momento (present continuous)."], ["He study English. ✗ → He studies English. ✓", "I’m going to the gym every day. ✗ → I go to the gym every day. ✓", "I’m needing help. ✗ → I need help. ✓"]),
    section("Perguntas frequentes", ["O present continuous pode falar de futuro? Sim — para planos combinados: I’m meeting her tomorrow. Todo verbo com -ing é present continuous? Não; -ing também aparece em gerúndios e outros tempos. ‘Always’ nunca vai com continuous? Vai, para reclamar de algo repetitivo: He’s always losing his keys."]),
    section("Continue praticando", ["Dominar os dois presentes é a base para falar da sua rotina e do seu momento. As aulas iniciais do curso trabalham justamente rotina e ações em andamento, e este tema conecta bem com o estudo de advérbios de frequência."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: o simple past",url:"/blog/simple-past-verbos-regulares-irregulares"},{label:"Como fazer perguntas em inglês",url:"/blog/como-fazer-perguntas-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "9 min"),
  article("simple-past-verbos-regulares-irregulares", "Gramática essencial", "Simple past: como usar o passado em inglês com verbos regulares e irregulares", "Aprenda a formar frases no passado em inglês, com as regras do -ed, os verbos irregulares mais comuns, perguntas, negativas e os erros que mais confundem.", "D", ["simple past", "simple past verbos regulares irregulares", "passado em inglês", "como usar o simple past", "verbos irregulares inglês", "regra do ed passado"], "O simple past é o tempo que você usa para falar de ações concluídas no passado — o que aconteceu ontem, no ano passado ou em qualquer momento já encerrado. A forma afirmativa tem dois caminhos: verbos regulares recebem -ed e verbos irregulares têm formas próprias. Já as perguntas e negativas seguem um padrão único com did. Neste guia você vê as regras, os verbos mais frequentes e os deslizes mais comuns de quem fala português.", [
    section("Quando usar o simple past", ["Use o simple past para ações terminadas em um momento passado, muitas vezes com marcadores de tempo como yesterday, last week, in 2020, two days ago ou when I was young. O foco está no que aconteceu e já acabou.", "Diferente do português, o verbo não muda com a pessoa: I worked, you worked, she worked — a forma é a mesma para todos. Isso vale tanto para regulares quanto para irregulares."], ["I watched a film yesterday. — Assisti a um filme ontem.", "We traveled to Chile last year. — Viajamos para o Chile no ano passado.", "He finished the course two months ago. — Ele terminou o curso há dois meses."]),
    section("Verbos regulares: a regra do -ed", ["A maioria dos verbos é regular: basta acrescentar -ed à forma base. Mas há pequenos ajustes de ortografia. Verbos terminados em -e recebem só -d (live → lived). Verbos terminados em consoante + y trocam o y por -ied (study → studied). E verbos curtos terminados em consoante-vogal-consoante tônica dobram a última letra (stop → stopped).", "A escrita é regular, mas a pronúncia do -ed varia entre /t/, /d/ e /ɪd/. Vale treinar esse som à parte para não criar uma sílaba a mais onde não existe."], ["work → worked / play → played", "live → lived / arrive → arrived", "study → studied / try → tried", "stop → stopped / plan → planned"], ["Terminou em -e? Só -d.", "Consoante + y? Troque por -ied.", "Consoante-vogal-consoante tônica? Dobre a consoante."]),
    section("Verbos irregulares: os mais comuns", ["Os verbos irregulares não seguem o -ed e precisam ser aprendidos um a um — mas a boa notícia é que os mais usados no dia a dia são poucos e se repetem muito. Em vez de decorar uma lista enorme, aprenda os campeões de frequência dentro de frases.", "Repare que alguns mudam totalmente (go → went), outros mudam só a vogal (begin → began) e alguns ficam iguais (put → put, cut → cut)."], ["be → was/were / have → had / do → did", "go → went / come → came / get → got", "see → saw / make → made / take → took", "say → said / give → gave / know → knew"]),
    section("Perguntas e negativas com did", ["Aqui está a parte que simplifica tudo: nas perguntas e negativas, o passado fica no auxiliar did, e o verbo principal volta à forma base. Ou seja, você não repete o -ed nem a forma irregular.", "Esse é um dos erros mais comuns de brasileiros: dizer “Did you went?”. O certo é Did you go? — o did já marca o passado, então went volta a go."], ["Did you call her? — Você ligou para ela?", "I didn’t go to the party. — Eu não fui à festa.", "She didn’t finish the test. — Ela não terminou a prova.", "What did you do yesterday? — O que você fez ontem?"]),
    section("Erros comuns no simple past", ["Além do “Did you went?”, há outros tropeços frequentes. Um é esquecer o -ed em verbos regulares na fala (dizer I work yesterday em vez de I worked). Outro é usar was/were com did (She wasn’t went). E há a confusão com o present perfect: com um tempo passado definido, o inglês pede simple past, não present perfect.", "Para fixar, conte uma história curta sobre o seu dia de ontem em cinco frases. Ao errar, confira a forma do verbo e refaça — o erro mostra exatamente o que revisar."], ["I didn’t saw it. ✗ → I didn’t see it. ✓", "He goed home. ✗ → He went home. ✓", "I’ve seen him yesterday. ✗ → I saw him yesterday. ✓"]),
    section("Perguntas frequentes sobre o simple past", ["Preciso decorar todos os verbos irregulares? Não de uma vez. Comece pelos 20 ou 30 mais comuns, que cobrem a maior parte das conversas, e amplie aos poucos. O verbo muda com he, she e it? Não: ao contrário do present simple (he works), o passado não acrescenta -s (he worked, para todos).", "Como diferencio simple past de present perfect? Se há um momento passado definido (yesterday, last year), use simple past. Se o foco é a experiência ou o resultado até agora, sem dizer quando, costuma ser present perfect."]),
    section("Continue praticando o passado", ["O simple past aparece em praticamente toda conversa, então vale praticá-lo em frases sobre a sua vida. As aulas do curso apresentam os verbos irregulares em contexto e os simulados cobram o passado em questões de leitura e uso.", "Depois de dominar o simple past, o próximo passo natural é compará-lo com o present perfect, que muda o foco do tempo."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: present perfect ou simple past",url:"/blog/present-perfect-vs-simple-past"},{label:"Como pronunciar o -ed dos verbos",url:"/blog/pronunciar-ed-passado-ingles"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("como-fazer-perguntas-em-ingles", "Gramática essencial", "Como fazer perguntas em inglês? Estruturas e exemplos", "Aprenda a montar perguntas em inglês: yes/no questions, perguntas com to be, com do/does/did, com palavras interrogativas e as perguntas de sujeito, com erros comuns.", "?", ["perguntas em inglês", "como fazer perguntas inglês", "question words", "como montar pergunta inglês", "yes no questions", "wh questions inglês"], "Fazer perguntas é essencial para qualquer conversa, mas a estrutura do inglês é diferente da do português: em vez de mudar só a entonação, o inglês geralmente inverte a ordem ou usa um verbo auxiliar. A boa notícia é que há poucos padrões, e eles se repetem. Neste guia você vê os tipos de pergunta — com to be, com do/does/did, com palavras interrogativas (wh- questions) e as perguntas de sujeito — além dos erros mais comuns.", [
    section("Dois grandes tipos de pergunta", ["Há perguntas de sim/não (yes/no questions), que começam por um verbo ou auxiliar e se respondem com yes ou no, e perguntas abertas (wh- questions), que começam por uma palavra interrogativa (what, where, when…) e pedem informação.", "Em ambas, a chave é a inversão ou o uso de um auxiliar. Entendido isso, basta escolher o verbo certo."], undefined, ["yes/no → começa pelo verbo/auxiliar: Are you…? Do you…?", "wh- → começa pela palavra interrogativa: What…? Where…?"]),
    section("Perguntas com o verbo to be", ["Quando o verbo da frase é to be (am, is, are, was, were), a pergunta se forma invertendo o verbo e o sujeito — sem auxiliar. You are tired → Are you tired?", "Isso vale no presente e no passado do to be."], ["Are you tired? — Você está cansado?", "Is she your sister? — Ela é sua irmã?", "Where is the station? — Onde fica a estação?", "Were they at home? — Eles estavam em casa?"]),
    section("Perguntas com do, does e did", ["Quando o verbo principal NÃO é to be, você precisa de um auxiliar. No simple present, use do (I/you/we/they) ou does (he/she/it). No simple past, use did para todos. Depois do auxiliar, o verbo principal volta à forma base.", "É aqui que mora o erro mais comum: com does e did, o verbo principal não leva -s nem passado. Does she works ✗ → Does she work ✓."], ["Do you work here? — Você trabalha aqui?", "Does he speak English? — Ele fala inglês?", "Did she call you? — Ela ligou para você?", "What time does it start? — A que horas começa?"]),
    section("Perguntas com palavras interrogativas (wh-)", ["As wh- questions começam por who (quem), what (o quê), where (onde), when (quando), why (por quê), which (qual), whose (de quem) e how (como). A palavra interrogativa vem primeiro; depois segue a mesma estrutura com to be ou com auxiliar.", "How combina com outras palavras para medir: how much (quanto, incontável), how many (quantos), how long (quanto tempo), how old (que idade)."], ["What do you like? — Do que você gosta?", "Where are you from? — De onde você é?", "Why did you leave? — Por que você foi embora?", "How much is this? — Quanto custa isto?"]),
    section("A exceção: perguntas de sujeito", ["Há um caso especial. Quando a pergunta é sobre o sujeito da frase (quem ou o que faz a ação), você NÃO usa do/does/did — o verbo fica na forma afirmativa normal. Compare: Who called you? (quem é o sujeito) não leva did, mas Who did you call? (você é o sujeito) leva.", "Essa diferença confunde, mas a regra é: se who/what é quem pratica a ação, pergunte direto, sem auxiliar."], ["Who lives here? — Quem mora aqui? (não ‘Who does live’)", "What happened? — O que aconteceu? (não ‘What did happen’)", "Who wants coffee? — Quem quer café?"]),
    section("Erros comuns ao perguntar", ["Além do ‘Does she works?’, outros deslizes frequentes: esquecer o auxiliar (You like coffee? em vez de Do you like coffee?), usar auxiliar com to be (Do you are tired? ✗ → Are you tired? ✓), e repetir o passado (Did you went? ✗ → Did you go? ✓).", "Para fixar, transforme frases afirmativas em perguntas: She works here → Does she work here? He went home → Did he go home?"], ["Does she works? ✗ → Does she work? ✓", "Do you are happy? ✗ → Are you happy? ✓", "Did you went? ✗ → Did you go? ✓"]),
    section("Perguntas frequentes", ["Como faço uma pergunta educada e indireta? Use Could you tell me…? seguido da ordem afirmativa: Could you tell me where the station is? Preciso de do/does com ‘can’, ‘will’? Não — modais (can, will, should) invertem direto: Can you help? Where está sempre com to be? Não; depende do verbo: Where do you live? usa do."]),
    section("Continue praticando", ["Perguntar bem é o que mantém uma conversa viva. As aulas do curso trabalham perguntas desde o início, e vale combinar este tema com as perguntas indiretas e educadas e com o estudo do present e do past simple."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Perguntas indiretas e mais educadas",url:"/blog/perguntas-indiretas-educadas-ingles"},{label:"Simple present ou present continuous",url:"/blog/simple-present-vs-present-continuous"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("there-is-there-are", "Gramática essencial", "There is e there are: como dizer que algo existe em inglês", "Aprenda a usar there is e there are para dizer que algo existe ou está em um lugar, no singular, no plural, em perguntas, negativas e outros tempos verbais.", "∃", ["there is there are", "there is there are diferença", "existe em inglês", "como usar there is there are", "there was there were", "há em inglês there is"], "There is e there are são a forma de dizer em inglês que algo existe ou está presente em um lugar — equivalem ao nosso ‘há’, ‘tem’ ou ‘existe(m)’. A escolha entre os dois depende de uma coisa só: se o que vem depois está no singular ou no plural. Neste guia você aprende a regra, as contrações, as perguntas e negativas, as versões no passado e no futuro, e os erros mais comuns.", [
    section("A regra básica: singular ou plural", ["Use there is com um substantivo no singular ou incontável, e there are com substantivos contáveis no plural. O que decide o verbo é o substantivo que vem logo depois — não a ideia de quantidade em geral.", "Em português dizemos ‘há’ ou ‘tem’ para os dois casos; em inglês, o verbo concorda com o que existe. There is a book (um livro); there are three books (três livros)."], ["There is a café nearby. — Há um café aqui perto.", "There are two cafés on this street. — Há dois cafés nesta rua.", "There is some water in the bottle. — Há um pouco de água na garrafa."], ["there is → singular e incontáveis", "there are → plural"]),
    section("Contrações e uso na fala", ["Na fala e na escrita informal, there is vira there’s. Já there are raramente é contraído na escrita, mas na fala soa como there’re, bem reduzido.", "Um detalhe de inglês falado: quando há uma lista começando no singular, é comum ouvir there’s mesmo antes de um plural (There’s a pen and two books). É aceito na conversa, mas na escrita cuidadosa o ideal é concordar com o primeiro item."], ["There’s a problem. — Há um problema.", "There’s a café and two shops. — Tem um café e duas lojas. (fala)"]),
    section("Perguntas e respostas curtas", ["Para perguntar, inverta there e o verbo: Is there…? / Are there…? As respostas curtas repetem o verbo: Yes, there is / No, there isn’t; Yes, there are / No, there aren’t.", "Com perguntas, é muito comum usar any antes de plurais e incontáveis: Is there any milk? Are there any seats?"], ["Is there a bank nearby? — Há um banco aqui perto?", "Are there any questions? — Há alguma pergunta?", "Yes, there is. / No, there aren’t. — Há, sim. / Não há."]),
    section("Negativas: isn't, aren't e no/any", ["Para negar, acrescente not ao verbo: there isn’t, there aren’t. Com substantivos contáveis no plural e incontáveis, use any na negativa: there isn’t any, there aren’t any.", "Você também pode negar com no e sem any: There is no sugar = There isn’t any sugar. As duas formas são corretas."], ["There isn’t a pharmacy here. — Não há farmácia aqui.", "There aren’t any chairs. — Não há cadeiras.", "There is no time. — Não há tempo."]),
    section("There was, there were e there will be", ["There is / there are muda com o tempo verbal. No passado, use there was (singular/incontável) e there were (plural). No futuro, use there will be para os dois. Com modais e present perfect, é there might be, there has been, etc.", "A lógica de singular x plural continua a mesma no passado: o verbo concorda com o substantivo."], ["There was a party last night. — Houve uma festa ontem à noite.", "There were many people there. — Havia muitas pessoas lá.", "There will be a test next week. — Haverá uma prova na semana que vem."]),
    section("Erros comuns com there is / there are", ["O erro mais frequente de brasileiros é usar have para dizer ‘há’ ou ‘tem’: “Have a café here” (✗). Em inglês, existência é there is/there are; have é posse (I have a car). Outro deslize é não concordar o verbo: there is two books (✗) → there are two books.", "Cuidado também com it is x there is: It is a café = é um café (identifica); There is a café = há um café (afirma que existe)."], ["Have many people here. ✗ → There are many people here. ✓", "There is three rooms. ✗ → There are three rooms. ✓"]),
    section("Perguntas frequentes", ["There’s pode ser usado com plural? Na fala informal, às vezes sim, mas na escrita use there are com plural. Como digo ‘não tem nada’? There isn’t anything / There is nothing. Qual a diferença de there is para it is? There is afirma existência; it is identifica ou descreve algo específico."]),
    section("Continue praticando", ["There is e there are aparecem em descrições de lugares, casas e cidades — temas das primeiras aulas do curso. Vale combinar este tema com o estudo de artigos (a, an, the) e de quantificadores (some, any, much, many)."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: a, an e the",url:"/blog/a-an-the-artigos-ingles"},{label:"Some, any, much e many",url:"/blog/some-any-much-many"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("some-any-much-many", "Gramática essencial", "Some, any, much e many: como falar de quantidades em inglês", "Aprenda a escolher entre some, any, much, many e a lot of conforme o substantivo e o tipo de frase, com a base de contáveis e incontáveis e os erros mais comuns.", "∑", ["some any much many", "quantificadores inglês", "contáveis incontáveis", "diferença some any", "much ou many", "a lot of inglês"], "Some, any, much, many e a lot of são os quantificadores: palavras que indicam quantidade sem dar um número exato. Escolher o certo depende de duas coisas — se o substantivo é contável ou incontável, e se a frase é afirmativa, negativa ou pergunta. Entendida essa base, o resto se encaixa. Neste guia você vê a regra de cada um, como combiná-los e os deslizes mais comuns de brasileiros.", [
    section("A base: contáveis e incontáveis", ["Antes de escolher o quantificador, identifique o substantivo. Contáveis podem ser contados e têm plural: a book / two books, an apple / apples. Incontáveis não se contam em unidades e não têm plural normal: water, time, money, information, advice.", "Essa distinção decide muita coisa: many e few vão com contáveis; much e little vão com incontáveis. Alguns substantivos que são contáveis em português são incontáveis em inglês (information, advice, furniture), o que gera erro."], undefined, ["contáveis → a car, cars; an idea, ideas", "incontáveis → water, money, time, information"]),
    section("Many com contáveis, much com incontáveis", ["Use many com substantivos contáveis no plural (many books, many people) e much com incontáveis (much time, much water). Nas perguntas de quantidade, isso aparece em How many? (quantos) e How much? (quanto).", "Na prática, much e many em frases afirmativas soam formais; na conversa do dia a dia, a lot of é muito mais comum. Já em perguntas e negativas, much e many são naturais."], ["How many people are coming? — Quantas pessoas vêm?", "How much water do we need? — De quanta água precisamos?", "I don’t have much time. — Não tenho muito tempo.", "There aren’t many seats. — Não há muitos lugares."]),
    section("Some e any: a regra prática", ["Use some em frases afirmativas e em ofertas/pedidos educados; use any em perguntas neutras e em negativas. Os dois servem para contáveis no plural e para incontáveis.", "Há duas exceções importantes com some e any. Some aparece em perguntas quando você oferece ou pede algo (Would you like some coffee?). E any pode significar ‘qualquer’ em frases afirmativas (Any ticket works)."], ["We have some apples. — Temos algumas maçãs.", "Do you have any questions? — Você tem alguma pergunta?", "There isn’t any milk. — Não há leite nenhum.", "Would you like some tea? — Você aceita um chá?"]),
    section("A lot of: o coringa da conversa", ["A lot of (ou lots of, mais informal) combina tanto com contáveis quanto com incontáveis e é a forma mais usada na conversa para dizer ‘muito/muitos’ em frases afirmativas: a lot of friends, a lot of money.", "Por isso, quando estiver em dúvida entre much e many numa afirmação, a lot of quase sempre resolve e soa natural."], ["She has a lot of friends. — Ela tem muitos amigos.", "We spent a lot of money. — Gastamos muito dinheiro.", "There’s lots of time. — Há bastante tempo."]),
    section("Few, little e outras quantidades", ["Para pouca quantidade: a few vai com contáveis (a few friends = alguns amigos) e a little com incontáveis (a little time = um pouco de tempo). Sem o a, few e little ganham tom negativo (few friends = poucos amigos, quase nenhum).", "Esses quantificadores completam o quadro e deixam a fala mais precisa."], ["I have a few questions. — Tenho algumas perguntas.", "There’s a little milk left. — Sobrou um pouco de leite.", "Few people came. — Pouca gente veio."]),
    section("Erros comuns de brasileiros", ["Os deslizes mais frequentes: usar many com incontável (many informations ✗ → much information ✓, e sem -s: information não tem plural), usar some em pergunta neutra (Do you have some money? em vez de any), e traduzir ‘muito’ sempre por very (very people ✗ → many people ✓).", "Lembre também que advice, information, furniture e money são incontáveis: an advice ✗ → a piece of advice ✓."], ["many informations ✗ → much information ✓", "Do you have some time? (neutra) → Do you have any time? ✓", "very friends ✗ → many friends ✓"]),
    section("Perguntas frequentes", ["Some vai em pergunta? Sim, em ofertas e pedidos: Can I have some water? É much ou many com ‘money’? Money é incontável: much money. ‘A lot of’ é informal demais? Não — é neutro e serve em quase tudo; em textos muito formais, much/many podem ser preferidos. Qual a diferença de ‘few’ para ‘a few’? A few = alguns (positivo); few = poucos (negativo)."]),
    section("Continue praticando", ["Os quantificadores aparecem sempre que você fala de compras, comida, tempo e dinheiro. As aulas do curso os apresentam em contexto, e este tema conecta diretamente com there is/there are e com os artigos a, an, the."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: there is e there are",url:"/blog/there-is-there-are"},{label:"A, an e the: os artigos",url:"/blog/a-an-the-artigos-ingles"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("pronunciar-ed-passado-ingles", "Pronúncia", "Como pronunciar o -ed dos verbos no passado?", "Aprenda os três sons de -ed e pratique com exemplos comuns.", "ED", ["pronunciar ed inglês", "pronúncia verbos passado", "final ed"], "A terminação -ed dos verbos regulares no passado tem três pronúncias: /t/, /d/ ou /ɪd/. A escolha depende do último som do verbo, não apenas da última letra escrita.", [
    section("O som /ɪd/ cria uma sílaba extra", ["Depois dos sons /t/ e /d/, a terminação é pronunciada como uma sílaba extra, semelhante a ‘id’."], ["wanted — /ˈwɒntɪd/", "needed — /ˈniːdɪd/"]),
    section("Depois de sons surdos, geralmente /t/", ["Sons como /k/, /p/, /s/ e /ʃ/ costumam levar à pronúncia /t/."], ["worked — termina com /t/", "washed — termina com /t/"]),
    section("Depois de sons sonoros, geralmente /d/", ["Após vogais e muitos sons sonoros, a terminação costuma soar /d/. Pratique ouvindo e repetindo o verbo inteiro."], ["played — termina com /d/", "cleaned — termina com /d/"]),
  ], "6 min"),
  article("pronuncia-s-es-plurais-ingles", "Pronúncia", "Como pronunciar o S e o ES no plural em inglês?", "Entenda as pronúncias /s/, /z/ e /ɪz/ das terminações de plurais e verbos.", "S/Z", ["pronúncia s plural inglês", "plural es pronúncia", "som z inglês"], "A terminação escrita -s ou -es pode soar /s/, /z/ ou /ɪz/. Para escolher a pronúncia, observe o último som do substantivo ou verbo, não só a letra final.", [
    section("O som /ɪz/ aparece depois de sons sibilantes", ["Depois de sons como /s/, /z/, /ʃ/ e /tʃ/, uma sílaba extra facilita a pronúncia."], ["buses — /ɪz/", "watches — /ɪz/"]),
    section("/s/ depois de sons surdos", ["Após sons como /p/, /t/ e /k/, a terminação geralmente soa /s/."], ["cups — /s/", "cats — /s/", "books — /s/"]),
    section("/z/ depois de vogais e sons sonoros", ["Após vogais e muitos sons sonoros, o final costuma soar /z/."], ["days — /z/", "pens — /z/", "plays — /z/"]),
  ]),
  article("falsos-cognatos-ingles-portugues", "Vocabulário e uso", "Falsos cognatos em inglês: palavras que parecem, mas não significam o mesmo", "Evite traduzir automaticamente palavras parecidas com o português.", "≠", ["falsos cognatos inglês português", "false friends", "palavras parecidas inglês"], "Falsos cognatos são palavras parecidas entre duas línguas que têm significados diferentes, total ou parcialmente. A semelhança visual pode ajudar a lembrar algumas palavras, mas também pode induzir a erros de interpretação.", [
    section("Alguns exemplos que confundem", ["Observe o significado em contexto, pois certas palavras podem ter mais de um uso."], ["actually = na verdade (não ‘atualmente’)", "pretend = fingir (não ‘pretender’)", "parents = pais (não ‘parentes’)"]),
    section("Como confirmar o sentido", ["Leia a frase inteira, procure exemplos confiáveis e confira a classe gramatical. Se uma tradução literal deixar a frase estranha, investigue antes de concluir que entendeu."]),
    section("Aprenda a palavra dentro de uma frase", ["Anote uma combinação real e crie um exemplo seu. Assim você aprende significado e uso, não apenas um par de traduções."], ["I actually live in Recife. — Na verdade, moro em Recife."]),
  ], "6 min"),
  article("como-aprender-vocabulario-ingles", "Vocabulário", "Como aprender vocabulário em inglês e lembrar das palavras", "Combine contexto, recuperação ativa e revisão espaçada para construir vocabulário utilizável.", "Aa", ["como aprender vocabulário inglês", "ampliar vocabulário", "aprender palavras inglês"], "Para aprender vocabulário em inglês, encontre palavras em frases compreensíveis, tente recuperá-las sem olhar e use-as em uma situação própria. Uma lista de traduções pode ser referência, mas não mostra por si só como a palavra funciona numa frase.", [
    section("Escolha palavras úteis para seu objetivo", ["Priorize termos que aparecem em textos, conversas ou temas que você realmente estuda. Não é necessário guardar toda palavra desconhecida numa primeira leitura."]),
    section("Registre significado, combinação e exemplo", ["Anote a palavra com uma expressão comum e uma frase curta. Isso reduz a chance de memorizar uma tradução inadequada ao contexto."], ["make a decision — tomar uma decisão", "I need to make a decision today. — Preciso tomar uma decisão hoje."]),
    section("Recupere e revise", ["Cubra a resposta, tente lembrar e volte ao material em dias diferentes. Ao errar, confira e faça um novo exemplo — o erro mostra o que vale revisar."]),
  ], "6 min"),
  article("como-entender-ingles-falado-listening", "Listening", "Como entender inglês falado sem traduzir cada palavra", "Pratique listening em etapas para acompanhar a ideia geral e notar detalhes gradualmente.", "♫", ["entender inglês falado", "listening inglês", "treinar compreensão oral"], "Para entender inglês falado, comece procurando a ideia geral; depois escute novamente para localizar informações específicas. Tentar traduzir cada palavra em tempo real pode fazer você perder o restante da mensagem.", [
    section("Primeira escuta: identifique o contexto", ["Pergunte a si mesmo quem está falando, onde estão e sobre qual assunto. Não pause a cada palavra desconhecida."]),
    section("Segunda escuta: procure pistas", ["Ouça novamente e foque em nomes, horários, lugares ou palavras repetidas. O contexto e as palavras vizinhas ajudam a inferir significados."]),
    section("Use transcrição depois de tentar", ["Se houver transcrição, leia após uma ou duas escutas. Marque o trecho difícil, confira o que ouviu e repita uma parte curta. Escolha áudios adequados ao seu nível e faça pausas quando precisar."]),
  ]),
  article("como-melhorar-leitura-ingles", "Reading", "Como melhorar a leitura em inglês usando contexto", "Leia para entender ideias e pistas antes de recorrer à tradução palavra por palavra.", "▤", ["melhorar leitura inglês", "reading inglês", "ler em inglês iniciante"], "Para ler melhor em inglês, faça uma primeira leitura em busca da ideia central. Depois volte para localizar detalhes e investigar palavras realmente importantes. Nem toda palavra desconhecida impede a compreensão.", [
    section("Antes de começar, observe o texto", ["O título, as imagens, os subtítulos e o formato dão pistas sobre o assunto. Use essas pistas para formular uma expectativa antes de ler."]),
    section("Leia em duas passagens", ["Na primeira, descubra tema e intenção. Na segunda, procure detalhes que respondam a uma pergunta, como quem fez algo ou quando aconteceu."]),
    section("Decida quais palavras pesquisar", ["Tente inferir palavras secundárias pelo contexto. Consulte um dicionário quando o termo for central, aparecer repetidamente ou mudar o sentido da frase."], ["The shop closes at six, so we should leave soon. — O horário de fechar ajuda a inferir o sentido de closes."]),
  ]),
  article("perder-medo-de-falar-ingles", "Speaking", "Como perder o medo de falar inglês? Prática em passos pequenos", "Reduza a pressão com objetivos curtos, preparação e conversas compatíveis com seu nível.", "…", ["medo de falar inglês", "como praticar speaking", "vergonha falar inglês"], "Falar uma língua que você está aprendendo pode dar insegurança. Em vez de esperar pelo momento em que não cometerá erros, pratique em situações curtas e previsíveis, com objetivos pequenos e espaço para tentar novamente.", [
    section("Comece com uma fala preparada", ["Escolha um tema familiar e prepare três frases. Depois repita com pequenas mudanças para não depender de decorar um texto inteiro."], ["I like music. I listen to pop music at home. My favourite singer is…"]),
    section("Pratique em etapas", ["Fale sozinho, grave apenas se se sentir confortável, repita uma atividade conhecida e depois tente uma troca curta com alguém de confiança. Gravações são opcionais; não precisa enviar áudio a terceiros."]),
    section("Trate erros como informação", ["Escolha um ponto para ajustar por vez, como pronunciar o final de uma palavra ou formular perguntas. Fluência não significa ausência total de erros; depende também de conseguir comunicar a ideia e seguir a conversa."]),
  ], "6 min"),
  article("frases-para-se-apresentar-em-ingles", "Conversação", "Como se apresentar em inglês: frases para começar uma conversa", "Use expressões simples para dizer seu nome, origem, ocupação e interesses.", "Hi!", ["se apresentar em inglês", "frases apresentação inglês", "introdução inglês"], "Uma apresentação simples em inglês pode incluir seu nome, de onde você é, o que faz e um interesse. Escolha apenas as informações que fazem sentido para a situação; não precisa recitar todos os detalhes pessoais.", [
    section("Comece com nome e origem", ["Use frases curtas e uma pergunta de volta para manter a conversa."], ["Hi, I’m Lucas. — Oi, eu sou Lucas.", "I’m from Brazil. Where are you from? — Sou do Brasil. De onde você é?"]),
    section("Fale de estudo, trabalho ou interesses", ["Adapte a apresentação ao contexto. Em inglês, é comum dizer I’m a student ou I work in…"], ["I’m a student. — Sou estudante.", "I work in healthcare. — Trabalho na área da saúde.", "I enjoy reading. — Gosto de ler."]),
    section("Exemplo curto e natural", ["Use as frases como ponto de partida e troque os dados pelos seus. Em encontros profissionais, prefira informações relevantes à conversa."], ["Hello, I’m Maya. I’m from Brazil, and I study design. I enjoy drawing. What about you?"]),
  ], "5 min"),
  article("email-simples-em-ingles", "Writing", "Como escrever um e-mail simples em inglês", "Organize saudação, objetivo, detalhes e encerramento com frases claras e educadas.", "@", ["escrever email inglês", "e-mail simples inglês", "saudações e encerramento inglês"], "Um e-mail simples em inglês pode ter uma saudação, o motivo do contato, os detalhes necessários e um encerramento. Ajuste o grau de formalidade à pessoa e à situação; não existe uma frase única para todos os casos.", [
    section("Use uma saudação adequada", ["Hi é comum em mensagens informais. Dear pode ser usado em contextos mais formais, especialmente quando você conhece o nome da pessoa."], ["Hi Sam, — Oi, Sam.", "Dear Ms Lee, — Prezada Sra. Lee."]),
    section("Explique o objetivo logo no início", ["Uma primeira frase direta ajuda a pessoa a entender por que você escreveu."], ["I’m writing to ask about the course schedule. — Escrevo para perguntar sobre o horário do curso.", "Could you please send me the details? — Você poderia me enviar os detalhes, por favor?"]),
    section("Feche com cortesia e revise", ["Escolha um encerramento compatível com a formalidade e revise nome, data e pedido antes de enviar."], ["Thank you for your help. — Obrigado/obrigada pela ajuda.", "Best regards, — Atenciosamente,"]),
  ], "6 min"),

  article("comparatives-em-ingles", "Gramática essencial", "Comparativos em inglês: como comparar pessoas e coisas", "Aprenda a formar o comparativo dos adjetivos em inglês: a regra do -er, o more para adjetivos longos, as formas irregulares, as mudanças de ortografia e os erros comuns.", "↔", ["comparativos inglês", "comparar em inglês", "comparative adjectives", "como usar comparativo inglês", "er more than inglês", "adjetivos comparativos inglês"], "Comparar faz parte de qualquer conversa: dizer que algo é maior, melhor ou mais caro que outra coisa. Em inglês, o comparativo dos adjetivos segue duas estratégias principais, decididas pelo tamanho do adjetivo: os curtos recebem -er e os longos usam more. Depois do comparativo, than introduz o segundo elemento. Neste guia você vê as regras, as mudanças de ortografia, as formas irregulares e os deslizes mais comuns.", [
    section("A regra geral: curto x longo", ["A escolha depende do número de sílabas do adjetivo. Adjetivos curtos (uma sílaba) recebem -er: tall → taller. Adjetivos longos (três sílabas ou mais) usam more: expensive → more expensive. Os de duas sílabas variam — muitos com -y usam -er (happy → happier), outros usam more.", "Em todos os casos, than liga as duas coisas comparadas, equivalendo ao ‘(do) que’ do português."], undefined, ["1 sílaba → adjetivo + -er + than", "2 sílabas terminadas em -y → troca y por -ier", "3+ sílabas → more + adjetivo + than"]),
    section("Adjetivos curtos: -er + than", ["Acrescente -er ao adjetivo curto. Há ajustes de ortografia: adjetivos terminados em -e recebem só -r (nice → nicer); os terminados em consoante-vogal-consoante dobram a última letra (big → bigger); os terminados em -y trocam por -ier (easy → easier).", "Depois vem than para introduzir a comparação."], ["My room is smaller than yours. — Meu quarto é menor que o seu.", "This bag is bigger than that one. — Esta bolsa é maior que aquela.", "Today is hotter than yesterday. — Hoje está mais quente que ontem.", "This exercise is easier than the last one. — Este exercício é mais fácil que o anterior."]),
    section("Adjetivos longos: more + than", ["Com adjetivos de duas ou mais sílabas (sobretudo três ou mais), use more antes do adjetivo, sem alterar sua forma: more difficult, more interesting, more expensive.", "O erro clássico aqui é juntar as duas estratégias: nunca use -er e more ao mesmo tempo (more easier ✗)."], ["This exercise is more difficult than the last one. — Este exercício é mais difícil que o último.", "She is more careful than me. — Ela é mais cuidadosa do que eu.", "This phone is more expensive than that one. — Este celular é mais caro que aquele."]),
    section("Formas irregulares", ["Alguns adjetivos muito comuns não seguem nenhuma das regras e têm formas próprias. Vale memorizá-las, porque aparecem o tempo todo: good → better, bad → worse, far → farther/further.", "Essas formas não levam -er nem more — já são o comparativo."], ["good → better: This option is better than the other one. — Esta opção é melhor que a outra.", "bad → worse: The weather is worse today. — O tempo está pior hoje.", "far → farther: The station is farther than I thought. — A estação é mais longe do que eu pensava."]),
    section("Outras formas de comparar", ["Além do comparativo de superioridade, há outras estruturas úteis. Para igualdade, use as … as (tão … quanto): She is as tall as her brother. Para inferioridade, use less … than (menos … que): This is less important than that. E para reforçar uma diferença, use much ou a lot antes do comparativo: much better, a lot cheaper.", "Essas estruturas deixam a comparação mais rica e natural."], ["He’s as fast as you. — Ele é tão rápido quanto você.", "This book is less interesting than the first one. — Este livro é menos interessante que o primeiro.", "It’s much colder today. — Está muito mais frio hoje."]),
    section("Erros comuns com comparativos", ["Os deslizes mais frequentes: usar more com adjetivo curto (more tall ✗ → taller ✓), combinar -er e more (more easier ✗ → easier ✓), e usar that no lugar de than (taller that me ✗ → taller than me ✓). Cuidado também com as formas irregulares: gooder e badder não existem.", "Para fixar, compare coisas da sua vida: a sua cidade e outra, o hoje e o ontem, dois aplicativos que você usa."], ["more tall ✗ → taller ✓", "more easier ✗ → easier ✓", "gooder ✗ → better ✓"]),
    section("Perguntas frequentes", ["Quando um adjetivo de 2 sílabas usa -er ou more? Os terminados em -y, -er, -ow geralmente usam -er (happier, narrower); muitos outros aceitam more. Na dúvida, more quase sempre soa aceitável. É ‘than me’ ou ‘than I’? Na conversa, than me é o natural; than I am é mais formal. O próximo passo depois do comparativo? O superlativo (the biggest, the most important)."]),
    section("Continue praticando", ["Depois de dominar o comparativo, o passo natural é o superlativo, que destaca o ‘mais’ de todos em um grupo. As aulas do curso trabalham adjetivos e comparações em contexto."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Em seguida: superlativos em inglês",url:"/blog/superlatives-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("superlatives-em-ingles", "Gramática essencial", "Como usar superlativos em inglês?", "Use superlativos para destacar alguém ou algo dentro de um grupo.", "★", ["superlativos inglês", "the most", "adjetivos superlativos"], "Use um superlativo para indicar que alguém ou algo tem uma característica no grau mais alto ou mais baixo dentro de um grupo. Em geral, adjetivos curtos recebem -est e os mais longos usam the most ou the least.", [
    section("Adjetivos curtos: the + -est", ["Muitos adjetivos curtos recebem -est. A grafia pode mudar: big → the biggest; happy → the happiest."], ["It’s the smallest room in the house. — É o menor quarto da casa.", "She is the happiest person here. — Ela é a pessoa mais feliz aqui."]),
    section("Adjetivos longos: the most", ["Com muitos adjetivos longos, use the most antes do adjetivo."], ["That was the most interesting part of the talk. — Essa foi a parte mais interessante da palestra."]),
    section("Inclua o grupo de comparação", ["Use in com lugares ou grupos e of com conjuntos de itens, quando for necessário esclarecer o conjunto."], ["the tallest building in the city", "the best day of the year"]),
  ]),
  article("can-could-habilidade-pedidos", "Gramática essencial", "Can e could: como falar de habilidades e fazer pedidos educados", "Compare can e could em habilidades, possibilidades e pedidos cotidianos.", "Can", ["can could diferença", "pedidos educados inglês", "habilidades inglês"], "Can é comum para falar de habilidade ou possibilidade no presente. Could pode falar de uma habilidade no passado ou tornar um pedido mais suave. A função depende do contexto.", [
    section("Habilidade e possibilidade", ["Depois de can e could, use o verbo na forma base, sem to."], ["I can swim. — Eu sei nadar.", "When I was five, I could read. — Quando eu tinha cinco anos, sabia ler."]),
    section("Pedidos", ["Could you…? costuma soar mais indireto que Can you…?, embora ambos possam ser educados dependendo do tom e da situação."], ["Can you help me, please? — Você pode me ajudar, por favor?", "Could you open the window? — Você poderia abrir a janela?"]),
    section("Evite adicionar -s", ["Can e could não mudam com he, she ou it: não se acrescenta -s ao modal nem ao verbo principal."], ["She can drive. ✓", "She cans drive. ✗"]),
  ]),
  article("should-must-have-to-obrigacao", "Gramática essencial", "Should, must e have to: como expressar conselho e obrigação", "Entenda diferenças comuns entre recomendação, obrigação e necessidade.", "!", ["should must have to", "conselho obrigação inglês", "modal verbs"], "Should costuma expressar conselho; must e have to podem indicar obrigação ou necessidade. A nuance depende do contexto, da fonte da regra e da variedade de inglês usada.", [
    section("Should para recomendações", ["Should + verbo base apresenta uma sugestão ou conselho, não necessariamente uma ordem."], ["You should get some rest. — Você deveria descansar um pouco."]),
    section("Must e have to para obrigação", ["Must pode expressar obrigação forte ou uma regra. Have to também comunica necessidade e é muito frequente na conversa. A distinção não é absoluta."], ["You must wear a seat belt. — Você deve usar cinto de segurança.", "I have to leave at six. — Tenho que sair às seis."]),
    section("A negativa muda o sentido", ["Mustn’t geralmente significa proibição. Don’t have to significa ausência de necessidade, não proibição."], ["You mustn’t park here. — Você não pode estacionar aqui.", "You don’t have to come early. — Você não precisa chegar cedo."]),
  ], "7 min"),
  article("present-perfect-vs-simple-past", "Gramática essencial", "Present perfect ou simple past: qual é a diferença e quando usar cada um?", "A dúvida mais comum do inglês intermediário. Entenda com clareza quando usar o present perfect e quando usar o simple past, com exemplos, marcadores de tempo e erros frequentes.", "↔", ["present perfect vs simple past", "diferença present perfect simple past", "quando usar present perfect", "have has past participle", "present perfect exemplos", "present perfect ou passado simples"], "Essa é provavelmente a dúvida de gramática que mais trava brasileiros no inglês intermediário, porque o português traduz os dois tempos de formas parecidas. A diferença central é de foco: o simple past situa a ação num momento passado definido e encerrado; o present perfect conecta o passado ao presente — uma experiência, um resultado atual ou algo que começou antes e segue relevante. Neste guia você vê a regra, os marcadores de tempo que denunciam cada um e os erros mais comuns.", [
    section("A diferença em uma frase", ["Pense assim: o simple past responde ‘quando?’ e aponta para um momento fechado no passado. O present perfect responde ‘e daí para agora?’ — ele não diz quando, porque o foco é o efeito ou a experiência até o presente.", "Compare: I lost my keys (simple past) só conta um fato passado; I’ve lost my keys (present perfect) sugere que ainda estou sem elas agora. A forma muda e o sentido também."], undefined, ["simple past → momento passado definido e encerrado (quando)", "present perfect → ligação com o presente (experiência, resultado, até agora)"]),
    section("Como formar cada tempo", ["O simple past usa o verbo no passado (regular com -ed ou a forma irregular): I worked, I went. O present perfect usa have ou has + particípio passado (a terceira coluna dos verbos): I have worked, she has gone.", "O particípio de verbos regulares é igual ao passado (worked–worked). Nos irregulares, às vezes muda: go–went–gone, see–saw–seen, do–did–done. Vale aprender as três formas juntas."], ["I finished the report yesterday. — Terminei o relatório ontem. (simple past)", "I have finished the report. — Já terminei o relatório. (present perfect)", "She has gone home. — Ela foi para casa (e não está aqui)."]),
    section("Simple past: tempo passado definido", ["Use o simple past sempre que houver (ou estiver subentendido) um momento passado específico: yesterday, last week, in 2020, two days ago, when I was a child, at 8 o’clock. Perguntas com When…? quase sempre pedem simple past.", "Se a conversa já fixou o momento no passado, continue no simple past para os detalhes."], ["I visited London in 2022. — Visitei Londres em 2022.", "We met last Friday. — Nós nos encontramos na sexta passada.", "When did you arrive? — Quando você chegou?"]),
    section("Present perfect: ligação com o presente", ["Use o present perfect para experiências de vida (sem dizer quando), ações recentes com efeito atual, e situações que começaram no passado e continuam. Marcadores típicos: ever, never, just, already, yet, so far, recently, for e since.", "Com for e since, o present perfect indica duração até agora: for marca o período (for three years) e since marca o ponto de início (since 2020)."], ["Have you ever tried sushi? — Você já experimentou sushi alguma vez?", "I’ve just finished. — Acabei de terminar.", "She has lived here for ten years. — Ela mora aqui há dez anos.", "We’ve known each other since 2015. — Nós nos conhecemos desde 2015."]),
    section("O erro mais comum: misturar os dois", ["Em inglês padrão, não se usa present perfect com um momento passado já encerrado. Dizer I’ve seen him yesterday está errado — como há yesterday, o certo é I saw him yesterday. Esse é o deslize número um de brasileiros.", "A regra prática: se você pode acrescentar ‘quando?’ e a resposta é um tempo fechado, use simple past. Se o foco é ‘até agora’ ou ‘na vida’, use present perfect."], ["I’ve seen him yesterday. ✗ → I saw him yesterday. ✓", "Did you ever go to Japan? → Have you ever been to Japan? (experiência de vida)", "I have finished it last night. ✗ → I finished it last night. ✓"]),
    section("Diferença entre inglês britânico e americano", ["Vale saber: o inglês americano costuma aceitar o simple past em casos onde o britânico prefere o present perfect, sobretudo com just, already e yet. Did you eat yet? soa natural nos EUA; Have you eaten yet? é mais britânico.", "Nos exames internacionais, o present perfect com esses marcadores costuma ser a resposta mais segura. Por isso vale praticá-lo bem."]),
    section("Perguntas frequentes", ["Been ou gone? I’ve been to Paris = fui e voltei (experiência); he’s gone to Paris = foi e ainda está lá. Posso usar present perfect com ‘this week’? Sim, enquanto a semana não terminou (I’ve studied a lot this week). For ou since? For + período (for two hours); since + ponto de início (since Monday)."]),
    section("Continue praticando", ["O jeito de dominar esse contraste é ver os dois tempos lado a lado em muitas frases. As aulas intermediárias do curso trabalham o present perfect em contexto, e os simulados de Cambridge e TOEFL cobram exatamente essa diferença."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Revise antes: o simple past",url:"/blog/simple-past-verbos-regulares-irregulares"},{label:"Just, already, yet, ever e never",url:"/blog/present-perfect-just-already-yet-ever-never"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("present-perfect-just-already-yet-ever-never", "Gramática essencial", "Como usar just, already, yet, ever e never com present perfect", "Veja como essas palavras mudam o foco de experiências e ações recentes.", "✓", ["just already yet ever never", "present perfect advérbios", "have you ever"], "Just, already, yet, ever e never aparecem frequentemente com o present perfect. Eles indicam uma ação recente, algo que já ocorreu, uma expectativa ainda não realizada ou uma experiência em algum momento da vida.", [
    section("Just e already", ["Just indica que algo aconteceu há pouco; already indica que ocorreu antes do esperado ou que já está feito. Normalmente aparecem entre have/has e o particípio."], ["I’ve just finished. — Acabei de terminar.", "She has already eaten. — Ela já comeu."]),
    section("Yet em perguntas e negativas", ["Yet costuma aparecer no fim da frase e pergunta se algo já aconteceu ou informa que ainda não aconteceu."], ["Have you called yet? — Você já ligou?", "I haven’t called yet. — Ainda não liguei."]),
    section("Ever e never para experiências", ["Ever é comum em perguntas sobre experiências; never informa que algo não aconteceu em nenhum momento até agora."], ["Have you ever tried sushi? — Você já experimentou sushi alguma vez?", "I’ve never flown alone. — Nunca viajei de avião sozinho/sozinha."]),
  ], "7 min"),
  article("a-an-the-artigos-ingles", "Gramática essencial", "A, an e the: como escolher o artigo certo em inglês?", "Entenda a diferença entre a, an e the, quando usar cada um, quando não usar artigo nenhum e os erros mais comuns de quem fala português.", "a/an", ["a an the inglês", "artigos definidos indefinidos", "quando usar the", "diferença a an the", "a ou an inglês", "quando não usar artigo inglês"], "Os artigos a, an e the são curtinhos, mas estão entre as maiores fontes de erro para brasileiros — em parte porque o inglês usa (e omite) artigos de um jeito diferente do português. A ideia central é simples: a/an apresentam algo não específico pela primeira vez; the aponta para algo que quem fala e quem ouve já conseguem identificar; e muitas vezes não se usa artigo nenhum. Neste guia você vê a regra, a escolha entre a e an, e os casos sem artigo.", [
    section("A diferença entre a/an e the", ["Use a ou an (o artigo indefinido) quando o substantivo é mencionado pela primeira vez ou não é específico — equivale a ‘um/uma’. Use the (o artigo definido) quando o ouvinte sabe exatamente a que você se refere — equivale a ‘o/a’.", "O exemplo clássico mostra os dois juntos: I saw a dog. The dog was friendly. Na primeira frase, o cachorro é novo na conversa (a); na segunda, já sabemos qual é (the)."], ["I saw a dog. The dog was friendly. — Vi um cachorro. O cachorro era amigável.", "She bought a car. The car is red. — Ela comprou um carro. O carro é vermelho."], ["a/an → algo novo ou não específico", "the → algo já identificado pelo contexto"]),
    section("A ou an? Depende do som, não da letra", ["Use a antes de som de consoante e an antes de som de vogal. O que importa é o som falado, não a letra escrita. Por isso dizemos a university (o U soa como /iu/, consoante) mas an hour (o H é mudo, começa com som de vogal).", "Fique atento a palavras que enganam: an umbrella, a European country, an MBA (soa ‘em-bi-ei’), a one-way ticket (soa ‘uan’)."], ["a university / a European / a one-hour class", "an hour / an umbrella / an honest man", "an apple / a banana / an idea"]),
    section("Quando usar the", ["Use the quando o referente é único ou identificável: algo já mencionado, algo único no mundo (the sun, the moon), algo único no contexto (the kitchen, da sua casa), ou com superlativos (the best). Também com muitos nomes geográficos: the United States, the Amazon, the Atlantic.", "The pode acompanhar singular, plural ou incontável — o que define é a identificação, não o número: the book, the books, the water."], ["Please close the door. — Por favor, feche a porta. (sabemos qual)", "The sun is bright today. — O sol está forte hoje.", "This is the best café in town. — Este é o melhor café da cidade."]),
    section("Quando NÃO usar artigo", ["Em inglês, não se usa artigo para falar de coisas em geral no plural ou incontáveis. Dogs need exercise (cães em geral) não leva the. Também não se usa artigo com a maioria dos nomes de refeições, idiomas, esportes, países (Brazil, not the Brazil) e com in/at/to + home, work, school, bed em sentido geral.", "Esse é um ponto em que o português engana: dizemos ‘a música me relaxa’ ou ‘o Brasil’, mas em inglês geral é Music helps me relax e Brazil."], ["Dogs need exercise. — Cães precisam de exercício.", "Music helps me relax. — Música me ajuda a relaxar.", "I speak Portuguese. — Eu falo português. (não ‘the Portuguese’)", "She’s at home / at work. — Ela está em casa / no trabalho."]),
    section("Erros comuns de brasileiros", ["Os deslizes mais frequentes vêm de traduzir o uso português. Colocar the em generalizações (The dogs are loyal ✗ quando se fala de cães em geral), usar the com países comuns (the Brazil ✗), e esquecer a/an com profissões (She is doctor ✗ → She is a doctor ✓).", "Outra confusão é omitir o artigo onde o inglês precisa dele: I have car ✗ → I have a car ✓. Sempre que um substantivo contável estiver no singular, ele quase sempre precisa de a/an ou the."], ["the Brazil ✗ → Brazil ✓", "He is engineer. ✗ → He is an engineer. ✓", "I need umbrella. ✗ → I need an umbrella. ✓"]),
    section("Perguntas frequentes", ["É ‘a hour’ ou ‘an hour’? An hour, porque o H é mudo. É ‘the breakfast’? Não para refeições em geral: I had breakfast. Uso artigo com nomes de pessoas? Não: Maria, not the Maria. Como sei se uso the ou nada? Pergunte se o ouvinte já sabe exatamente qual: se sim, the; se é geral, muitas vezes nenhum."]),
    section("Continue praticando", ["Artigos entram no automático com leitura e prática — raramente com regras decoradas. As aulas iniciais do curso apresentam a, an e the em contexto, e vale combinar este tema com there is/there are e com substantivos contáveis e incontáveis."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: there is e there are",url:"/blog/there-is-there-are"},{label:"Some, any, much e many",url:"/blog/some-any-much-many"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("first-conditional-em-ingles", "Gramática essencial", "Como formar o first conditional em inglês?", "Fale de situações futuras possíveis usando condição e resultado.", "If", ["first conditional", "if clause inglês", "condicional provável inglês"], "O first conditional descreve uma condição futura considerada possível e seu resultado provável. A forma comum é if + simple present, will + verbo base; apesar do sentido futuro, a oração com if normalmente usa presente.", [
    section("Condição e resultado", ["A oração com if apresenta a condição; a outra apresenta o resultado. As duas partes podem mudar de ordem."], ["If it rains, we’ll stay home. — Se chover, vamos ficar em casa.", "I’ll call you if I arrive early. — Vou ligar para você se chegar cedo."]),
    section("Pontuação e ordem", ["Quando if vem primeiro, use vírgula entre condição e resultado. Quando a oração com if vem depois, geralmente não se usa vírgula."]),
    section("Evite will logo após if", ["Na estrutura padrão para esse uso, mantenha o simple present na oração da condição."], ["If she has time, she’ll help us. ✓", "If she will have time, she’ll help us. ✗"]),
  ], "6 min"),
  article("word-stress-pronuncia-ingles", "Pronúncia", "Word stress em inglês: como perceber a sílaba tônica", "Treine a sílaba que recebe mais destaque para falar e reconhecer palavras com mais clareza.", "ˈ", ["word stress inglês", "sílaba tônica inglês", "pronúncia palavras"], "Word stress é o destaque dado a uma sílaba dentro de uma palavra. Em inglês, acertar esse destaque ajuda o ouvinte a reconhecer a palavra; não existe uma regra única que resolva todos os casos.", [
    section("Ouça antes de tentar adivinhar", ["Use um dicionário com áudio para ouvir a palavra e observar a marca de acento na transcrição fonética. Repita primeiro devagar e depois no ritmo normal."], ["TAble — destaque na primeira sílaba", "hoTEL — destaque na segunda sílaba"]),
    section("Aprenda palavras novas com o som", ["Ao registrar uma palavra, marque a sílaba forte com letras maiúsculas ou um sinal. Isso é útil especialmente em palavras longas ou pouco familiares."]),
    section("Algumas palavras mudam de classe e pronúncia", ["Há pares em que a tonicidade muda entre substantivo e verbo, embora isso não se aplique a todas as palavras."], ["REcord (substantivo) / reCORD (verbo)"]),
  ]),
  article("connected-speech-ligacao-sons", "Pronúncia e listening", "Connected speech: por que os sons se ligam no inglês falado?", "Entenda ligações e reduções comuns sem confundir fala natural com palavras diferentes.", "≈", ["connected speech inglês", "ligação de sons inglês", "redução fala inglesa"], "Na fala encadeada, palavras próximas podem se ligar, reduzir ou influenciar seus sons. Isso faz a conversa soar diferente da pronúncia isolada de cada palavra e pode dificultar o listening no começo.", [
    section("Consoante ligada à vogal seguinte", ["Quando uma palavra termina em consoante e a próxima começa com vogal, a fala pode parecer contínua."], ["pick it up — os sons podem se ligar entre palavras", "turn off — a sequência pode soar como um bloco"]),
    section("Formas fracas em palavras gramaticais", ["Artigos, preposições e auxiliares frequentemente ficam menos destacados quando não carregam a informação principal. A redução varia com ritmo e sotaque."]),
    section("Como treinar sem perder as palavras", ["Escolha um trecho curto com transcrição, ouça a ideia geral, acompanhe uma frase e observe onde as palavras se conectam. Não tente imitar um sotaque específico à força."]),
  ], "6 min"),
  article("vogais-curtas-longas-ingles", "Pronúncia", "Vogais curtas e longas em inglês: pratique pares como ship e sheep", "Perceba contrastes vocálicos que podem mudar o significado de uma palavra.", "iː", ["vogais inglês ship sheep", "vogais curtas longas", "pronúncia inglês pares mínimos"], "Em inglês, algumas diferenças entre vogais ajudam a distinguir palavras. O contraste de ship e sheep é um exemplo comum para estudantes de inglês, mas a duração não é o único fator: a qualidade da vogal e o sotaque também importam.", [
    section("Escute pares mínimos", ["Pares mínimos diferem por um som e ajudam a treinar a percepção. Ouça um modelo confiável antes de repetir."], ["ship / sheep — navio / ovelha", "sit / seat — sentar / assento"]),
    section("Observe a boca e o contexto", ["A vogal de sheep costuma ser mais anterior e tensa que a de ship em muitos sotaques. Não tente compensar só prolongando o som; observe a qualidade da vogal também."]),
    section("Pratique em passos curtos", ["Ouça, identifique qual palavra ouviu, confira e repita em uma frase. Sotaques diferentes podem realizar vogais de modos distintos; o objetivo é inteligibilidade, não copiar um único modelo."]),
  ]),
  article("contracoes-ingles-falado", "Pronúncia e listening", "Contrações comuns em inglês falado: o que você precisa reconhecer", "Aprenda formas contraídas frequentes para acompanhar conversas e entender diálogos.", "’", ["contrações inglês", "inglês falado contrações", "I’m don’t they’ve"], "Contrações juntam palavras e omitem letras na escrita, como I’m por I am e don’t por do not. São comuns em conversas e escrita informal; reconhecê-las ajuda no listening e no uso cotidiano.", [
    section("Contrações com to be", ["A forma contraída preserva o sujeito e combina o verbo em uma unidade."], ["I’m ready. — Estou pronto/pronta.", "They’re at home. — Eles estão em casa."]),
    section("Negativas contraídas", ["Don’t, doesn’t, didn’t, isn’t e aren’t são comuns na fala. Em redação acadêmica ou documentos formais, a forma completa pode ser preferível conforme a convenção."]),
    section("Cuidado com formas parecidas", ["Apostrofo pode marcar omissão, mas não é genitivo em todas as ocorrências. Aprenda cada forma com significado e contexto."], ["you’re = you are", "your = seu/sua"]),
  ]),
  article("ingles-no-restaurante", "Inglês para viagens", "Como pedir comida em inglês no restaurante", "Frases para consultar o cardápio, fazer pedidos e perguntar sobre ingredientes.", "☕", ["inglês restaurante", "pedir comida inglês", "frases restaurante inglês"], "No restaurante, você pode pedir com expressões como I’d like… ou Could I have…? Para perguntar sobre ingredientes, alergênicos ou opções, use uma pergunta clara e confirme a resposta se a informação for importante.", [
    section("Peça e consulte o cardápio", ["I’d like… é uma forma educada de dizer o que gostaria. Could I have…? também é comum."], ["I’d like the vegetable soup, please. — Eu gostaria da sopa de legumes, por favor.", "Could I have the menu? — Posso ver o cardápio?"]),
    section("Pergunte sobre ingredientes", ["Se você tem alergia ou restrição, diga isso claramente e peça confirmação. Não presuma que a equipe compreendeu um detalhe médico importante."], ["Does this contain peanuts? — Isto contém amendoim?", "I’m allergic to peanuts. Could you check with the kitchen? — Tenho alergia a amendoim. Você poderia confirmar com a cozinha?"]),
    section("Peça a conta", ["Use Could we have the bill, please? ou Could we have the check, please? A palavra pode variar conforme a região."]),
  ], "6 min"),
  article("ingles-para-compras", "Inglês para viagens", "Inglês para fazer compras: preços, tamanhos e pagamento", "Pergunte o preço, encontre um tamanho e confirme formas de pagamento com frases úteis.", "£", ["inglês compras", "perguntar preço inglês", "tamanho pagamento inglês"], "Em uma loja, você pode perguntar o preço, solicitar outro tamanho e confirmar como pagar. Frases curtas com please ajudam a manter o pedido claro e educado.", [
    section("Pergunte sobre preço e disponibilidade", ["Use How much is…? para perguntar o preço de um item singular e Do you have…? para verificar disponibilidade."], ["How much is this jacket? — Quanto custa esta jaqueta?", "Do you have this in blue? — Você tem isto em azul?"]),
    section("Tamanhos e provador", ["Peça outro tamanho ou pergunte onde pode experimentar. As convenções de tamanho variam por país e marca."], ["Do you have a smaller size? — Você tem um tamanho menor?", "Where can I try this on? — Onde posso experimentar?"]),
    section("Pagamento", ["Confirme o total, a forma de pagamento e a possibilidade de recibo quando necessário."], ["Can I pay by card? — Posso pagar com cartão?", "Could I have a receipt, please? — Poderia me dar um recibo, por favor?"]),
  ]),
  article("pedir-direcoes-ingles", "Inglês para viagens", "Como pedir e entender direções em inglês", "Pergunte como chegar a um lugar e confirme referências pelo caminho.", "⌖", ["pedir direções em inglês", "como chegar inglês", "instruções de caminho inglês"], "Para pedir direções, comece com Excuse me e diga o destino. Escute a sequência de ações e confirme pontos de referência, distância ou lado da rua quando necessário.", [
    section("Comece com uma pergunta clara", ["Where is…? pergunta onde fica um local; How do I get to…? pergunta como chegar."], ["Excuse me, where is the train station? — Com licença, onde fica a estação de trem?", "How do I get to the museum? — Como chego ao museu?"]),
    section("Entenda instruções frequentes", ["Reconheça verbos de movimento e referências espaciais."], ["Go straight. — Siga em frente.", "Turn left at the lights. — Vire à esquerda no semáforo.", "It’s across from the bank. — Fica em frente ao banco."]),
    section("Confirme para evitar enganos", ["Repita o ponto principal com uma pergunta de confirmação e use um mapa se o trajeto ou sua segurança depender da precisão."]),
  ]),
  article("ingles-transporte-publico", "Inglês para viagens", "Como usar inglês no transporte público", "Pergunte sobre plataforma, passagem, horários e conexões em ônibus e trens.", "⇄", ["inglês transporte público", "ônibus trem inglês", "passagem plataforma inglês"], "No transporte público, perguntas diretas ajudam a confirmar destino, plataforma, horário e tipo de passagem. Nomes e sistemas variam entre cidades; mostre o nome do destino escrito se a pronúncia causar dúvida.", [
    section("Confirme a rota e a plataforma", ["Pergunte se o transporte vai ao destino e de qual plataforma parte."], ["Does this train go to Oxford? — Este trem vai para Oxford?", "Which platform does it leave from? — De qual plataforma ele sai?"]),
    section("Compre passagem e pergunte sobre conexões", ["Use ticket para passagem e connection para conexão, em muitos contextos."], ["Where can I buy a ticket? — Onde posso comprar uma passagem?", "Do I need to change trains? — Preciso trocar de trem?"]),
    section("Confira horários", ["Pergunte quando parte ou chega e confira telas e avisos oficiais, especialmente se houver mudança de serviço."]),
  ], "6 min"),
  article("ingles-no-hotel", "Inglês para viagens", "Inglês para fazer check-in em um hotel", "Prepare-se para confirmar reserva, horário e pedidos simples na recepção.", "⌂", ["inglês hotel check-in", "frases recepção hotel", "reserva hospedagem inglês"], "Ao chegar a um hotel, informe o nome da reserva e confirme os detalhes. Tenha a confirmação acessível e pergunte se algo importante — como horário, acessibilidade ou cobrança — não estiver claro.", [
    section("Confirme a reserva", ["Diga que tem uma reserva e informe o nome usado no pedido."], ["I have a reservation under Silva. — Tenho uma reserva em nome de Silva.", "Could you confirm the dates? — Poderia confirmar as datas?"]),
    section("Pergunte sobre serviços e horários", ["Confirme horário de café da manhã, saída e acesso à internet diretamente com a equipe."], ["What time is breakfast? — Que horas é o café da manhã?", "What time is check-out? — Que horas é o check-out?"]),
    section("Explique um problema ou pedido", ["Descreva o problema de forma objetiva e peça ajuda. Para pagamentos, confirme o valor e a moeda antes de autorizar."], ["The key card isn’t working. — O cartão-chave não está funcionando.", "Could you help me with my luggage? — Poderia me ajudar com a bagagem?"]),
  ]),
  article("ingles-no-aeroporto", "Inglês para viagens", "Frases úteis em inglês no aeroporto", "Entenda perguntas de check-in, portão, embarque e bagagem.", "✈", ["inglês aeroporto", "check-in voo inglês", "portão embarque bagagem inglês"], "No aeroporto, siga as informações oficiais nos painéis e pergunte à equipe se estiver em dúvida. Vocabulário como check-in, gate, boarding e baggage ajuda a reconhecer instruções frequentes.", [
    section("Check-in e documento", ["Apresente seus documentos quando solicitados e peça ajuda para localizar o balcão correto."], ["Where is the check-in desk for flight BA123? — Onde fica o balcão do voo BA123?", "Can I check this bag? — Posso despachar esta mala?"]),
    section("Portão e embarque", ["Gate é portão; boarding é embarque. Confirme o portão no painel, pois ele pode mudar."], ["Has the gate changed? — O portão mudou?", "When does boarding begin? — Quando começa o embarque?"]),
    section("Peça esclarecimento com segurança", ["Se não entendeu uma instrução importante, peça para repetir ou mostrar a informação por escrito. Não adivinhe detalhes de voo ou documentos."]),
  ]),
  article("ingles-medico-farmacia", "Inglês para viagens", "Como explicar sintomas em inglês na farmácia ou em uma consulta", "Frases para descrever sintomas e pedir ajuda sem substituir orientação profissional.", "+", ["sintomas inglês", "inglês farmácia médico", "descrever dor inglês"], "Você pode descrever sintomas em inglês com frases simples, indicando o que sente, quando começou e se piorou. Este vocabulário não substitui avaliação médica; em urgências, procure os serviços locais de emergência.", [
    section("Diga o sintoma e quando começou", ["Use I have… para alguns sintomas e My… hurts para indicar uma parte do corpo dolorida."], ["I have a fever. — Estou com febre.", "My throat hurts. — Minha garganta dói.", "It started yesterday. — Começou ontem."]),
    section("Peça orientação ou ajuda para comunicar", ["Explique alergias e medicamentos que usa com informações precisas. Se não entender uma orientação médica, peça interpretação ou repetição."], ["I’m allergic to penicillin. — Tenho alergia à penicilina.", "Could you write that down, please? — Poderia escrever isso, por favor?"]),
    section("Não dependa de frases decoradas para urgências", ["Em uma emergência, priorize atendimento profissional e os números locais. Um guia de idioma não oferece diagnóstico ou recomendação de tratamento."]),
  ], "6 min"),
  article("marcar-consulta-por-telefone-ingles", "Inglês para situações práticas", "Como marcar ou alterar um horário por telefone em inglês", "Peça um horário, confirme a data e solicite repetição de informações por telefone.", "☎", ["marcar consulta inglês telefone", "appointment phone call english", "alterar horário inglês"], "Para marcar um horário por telefone, diga o motivo da ligação, peça uma data disponível e repita os detalhes para confirmar. Se datas ou números não estiverem claros, peça que a pessoa os diga novamente ou por extenso.", [
    section("Peça um horário", ["Appointment é usado para consulta ou compromisso marcado."], ["I’d like to make an appointment. — Gostaria de marcar uma consulta.", "Do you have anything available on Friday? — Há algum horário disponível na sexta-feira?"]),
    section("Altere ou cancele", ["Explique que precisa mudar o horário e ofereça uma alternativa, se souber."], ["I need to reschedule my appointment. — Preciso remarcar minha consulta.", "Could I change it to Monday morning? — Poderia mudar para segunda de manhã?"]),
    section("Confirme os detalhes", ["Repita data, horário, local e nome. Em contexto internacional, confirme dia e mês para evitar confusão entre formatos de data."]),
  ], "6 min"),
  article("small-talk-em-ingles", "Conversação", "Small talk em inglês: como iniciar uma conversa casual", "Use perguntas abertas e comentários leves para começar e manter uma conversa informal.", "…", ["small talk inglês", "conversa casual inglês", "iniciar conversa em inglês"], "Small talk é uma conversa casual e breve, comum em situações sociais e profissionais. Comece com um comentário apropriado ao contexto, faça uma pergunta simples e demonstre atenção sem insistir em assuntos pessoais.", [
    section("Escolha um assunto compartilhado", ["O local, um evento, o clima ou uma atividade em comum podem oferecer um início natural."], ["How are you enjoying the event? — O que está achando do evento?", "Have you tried the coffee here? — Você já experimentou o café daqui?"]),
    section("Pergunte e também compartilhe", ["Uma conversa não precisa ser uma entrevista. Responda à pergunta e acrescente um detalhe curto para dar continuidade."], ["What do you do? — O que você faz?", "I work in design. What about you? — Trabalho com design. E você?"]),
    section("Respeite limites e encerre com educação", ["Se a outra pessoa responder pouco ou parecer ocupada, encerre cordialmente. Evite presumir intimidade ou perguntar dados sensíveis."]),
  ], "6 min"),
  article("pedir-para-repetir-em-ingles", "Conversação", "Como pedir para alguém repetir ou falar mais devagar em inglês", "Frases educadas para solicitar repetição, esclarecimento ou uma explicação diferente.", "↻", ["pedir para repetir inglês", "fale mais devagar inglês", "could you repeat that"], "Quando não entender, peça repetição ou esclarecimento em vez de fingir que compreendeu. Uma pergunta curta e educada ajuda a manter a conversa e evita mal-entendidos.", [
    section("Peça para repetir", ["Use Could you repeat that, please? em muitas situações. Sorry? ou Pardon? podem aparecer, com diferenças regionais de formalidade."], ["Could you repeat that, please? — Poderia repetir, por favor?"]),
    section("Peça para falar mais devagar", ["A formulação com could you é um pedido; use please para manter o tom cordial."], ["Could you speak a little more slowly, please? — Poderia falar um pouco mais devagar, por favor?"]),
    section("Peça outra forma de explicar", ["Se uma palavra específica causou dúvida, diga qual foi ou peça que a pessoa escreva."], ["What does ‘receipt’ mean? — O que significa ‘receipt’?", "Could you write the address down? — Poderia anotar o endereço?"]),
  ]),
  article("entrevista-emprego-ingles", "Inglês para trabalho", "Como se preparar para uma entrevista de emprego em inglês", "Organize respostas claras sobre experiência, pontos fortes e interesse pela vaga.", "CV", ["entrevista emprego inglês", "job interview answers", "perguntas entrevista inglês"], "Para uma entrevista em inglês, prepare exemplos verdadeiros sobre sua experiência e pratique respostas claras, sem decorar um discurso rígido. O vocabulário e a formalidade dependem do setor e da vaga.", [
    section("Prepare uma apresentação breve", ["Resuma sua formação ou experiência relacionada ao cargo e o que procura agora."], ["I have three years of experience in customer support. — Tenho três anos de experiência em atendimento ao cliente."]),
    section("Responda com exemplos concretos", ["Ao falar de uma habilidade, conte uma situação real, sua ação e o resultado. Não invente experiência nem dados para impressionar."], ["In my last role, I organized… — No meu último cargo, organizei…"]),
    section("Faça perguntas sobre a vaga", ["Prepare perguntas sobre responsabilidades, equipe e próximos passos. Se não entendeu uma pergunta, peça esclarecimento antes de responder."]),
  ], "7 min"),
  article("ingles-para-reunioes-trabalho", "Inglês para trabalho", "Frases em inglês para participar de reuniões de trabalho", "Interrompa com educação, compartilhe uma ideia e confirme próximos passos.", "◎", ["inglês reuniões trabalho", "frases reunião inglês", "meeting phrases"], "Em uma reunião de trabalho, frases curtas ajudam a pedir a palavra, apresentar uma ideia, confirmar entendimento e resumir ações. Escolha o tom de acordo com a cultura e a formalidade da equipe.", [
    section("Entre na conversa com educação", ["Use expressões de introdução para acrescentar uma ideia ou fazer uma pergunta."], ["Could I add something? — Posso acrescentar uma coisa?", "I have a question about the timeline. — Tenho uma pergunta sobre o cronograma."]),
    section("Confirme o que ficou combinado", ["Ao final, repita responsável, tarefa e prazo para reduzir ambiguidades."], ["So, I’ll send the draft by Thursday. — Então, envio o rascunho até quinta-feira."]),
    section("Peça esclarecimento", ["Se uma sigla, prazo ou decisão não ficou clara, pergunte. Isso é mais seguro do que assumir e executar algo errado."]),
  ], "6 min"),
  article("mensagens-curtas-em-ingles", "Writing", "Como escrever mensagens curtas em inglês com clareza", "Organize pedidos, atualizações e respostas breves conforme o contexto.", "✉", ["mensagens curtas inglês", "escrever mensagem inglês", "text message english"], "Uma mensagem curta em inglês fica clara quando apresenta o objetivo logo no início, inclui os detalhes necessários e termina com uma pergunta ou próximo passo, se houver. O grau de formalidade depende de quem vai receber.", [
    section("Diga o motivo e a ação esperada", ["Evite mensagens vagas quando precisa de uma resposta específica."], ["Hi, could you send me the file today? — Oi, poderia me enviar o arquivo hoje?", "I’m running ten minutes late. — Vou me atrasar dez minutos."]),
    section("Ajuste tom e abreviações", ["Contrações são comuns em mensagens informais. Abreviações e emojis podem não funcionar em contextos profissionais ou com pessoas que você não conhece."]),
    section("Revise nomes, datas e anexos", ["Antes de enviar, verifique destinatário, horário e arquivo. Para combinar uma reunião, informe o fuso horário se as pessoas estiverem em lugares diferentes."]),
  ], "5 min"),
  article("como-escrever-paragrafo-ingles", "Writing", "Como organizar um parágrafo em inglês", "Use uma ideia principal, explicações e uma conclusão coerente em textos curtos.", "¶", ["escrever parágrafo inglês", "paragraph writing", "organizar texto inglês"], "Um parágrafo claro costuma apresentar uma ideia principal, desenvolvê-la com explicações ou exemplos e manter as frases relacionadas. Essa estrutura é uma ferramenta útil, não uma regra rígida para todo gênero textual.", [
    section("Apresente a ideia central", ["A primeira frase pode indicar o assunto do parágrafo. Evite introduzir vários temas sem explicar a relação entre eles."], ["Learning a language takes regular practice. — Aprender uma língua exige prática regular."]),
    section("Desenvolva com explicação ou exemplo", ["Acrescente uma razão, um detalhe ou um exemplo que ajude a sustentar a ideia."], ["For example, listening to a short dialogue can help learners notice everyday expressions. — Por exemplo, ouvir um diálogo curto pode ajudar estudantes a notar expressões do cotidiano."]),
    section("Revise conexão e clareza", ["Confira se cada frase contribui para o ponto central, se os pronomes têm referentes claros e se as conjunções expressam a relação pretendida."]),
  ], "6 min"),
  article("niveis-cefr-ingles-a1-c2", "Níveis e exames", "O que significam os níveis A1, A2, B1, B2, C1 e C2?", "Conheça a escala CEFR como referência de habilidades, não como certificado automático.", "CEFR", ["CEFR níveis inglês", "A1 A2 B1 B2 C1 C2", "nível de inglês"], "O CEFR, chamado também de Quadro Europeu Comum de Referência para Línguas, descreve seis níveis amplos de proficiência, de A1 a C2. Os descritores ajudam a falar sobre o que alguém consegue fazer em uma língua; não são, por si só, um teste ou certificado.", [
    section("A1 e A2: usuário básico", ["A1 envolve frases e interações muito simples com apoio; A2 descreve tarefas rotineiras e comunicação simples sobre assuntos familiares."]),
    section("B1 e B2: usuário independente", ["B1 envolve lidar com situações comuns e explicar assuntos familiares. B2 descreve compreensão mais ampla e participação mais independente em conversas e textos variados."]),
    section("C1 e C2: proficiência avançada", ["C1 envolve uso flexível em contextos complexos; C2 indica compreensão e expressão muito precisas. As descrições não significam perfeição em todas as habilidades."], ["Um teste curto pode sugerir um ponto de partida, mas não prova um nível CEFR nem substitui um exame oficial."]),
  ], "7 min"),
  article("diferenca-entre-a1-e-a2-ingles", "Níveis e exames", "A1 e A2 em inglês: o que muda entre os níveis iniciantes?", "Compare tarefas típicas dos níveis básicos sem tratá-los como notas universais.", "A1/A2", ["diferença A1 A2 inglês", "nível iniciante inglês", "CEFR A1 A2"], "A1 e A2 são faixas do nível básico no CEFR. De forma geral, A1 descreve comunicação muito simples com apoio; A2 descreve maior capacidade de lidar com tarefas rotineiras e informações familiares. Isso não determina uma fronteira idêntica para todas as pessoas.", [
    section("A1: expressões e necessidades imediatas", ["Uma pessoa em A1 pode usar frases simples para se apresentar, dar informações básicas e responder quando a outra pessoa fala devagar e ajuda."]),
    section("A2: mais autonomia em situações familiares", ["Em A2, a pessoa pode trocar informações em tarefas previsíveis, falar de rotina e compreender mensagens simples sobre assuntos familiares."]),
    section("Compare tarefas, não apenas gramática", ["Observe o que consegue fazer em leitura, escuta, fala e escrita. Uma atividade isolada ou uma lista de regras não define sozinha o nível global."]),
  ], "6 min"),
  article("diferenca-entre-b1-e-b2-ingles", "Níveis e exames", "B1 e B2 em inglês: como distinguir os níveis intermediários?", "Entenda diferenças gerais de autonomia e complexidade descritas pelo CEFR.", "B1/B2", ["diferença B1 B2 inglês", "nível intermediário CEFR", "B1 vs B2"], "B1 e B2 são níveis de usuário independente no CEFR. Em linhas gerais, B1 permite lidar com muitos assuntos familiares; B2 descreve compreensão e interação mais independentes em uma gama maior de temas, inclusive alguns abstratos.", [
    section("B1: comunicar-se em situações familiares", ["Uma pessoa em B1 pode entender os pontos principais de fala clara sobre temas conhecidos, narrar experiências e explicar brevemente opiniões ou planos."]),
    section("B2: sustentar interação mais ampla", ["B2 envolve acompanhar textos e discussões mais complexos, interagir com maior espontaneidade e apresentar argumentos com detalhes. O desempenho varia por habilidade e contexto."]),
    section("Use descritores com cautela", ["Essas são sínteses, não um teste de colocação. Consulte descritores oficiais e avaliações adequadas quando uma decisão formal depender do nível."]),
  ], "6 min"),
  article("gramatica-para-falar-ingles", "Speaking", "Preciso estudar gramática para falar inglês?", "Veja como gramática e prática oral podem se apoiar sem esperar dominar todas as regras.", "A↗", ["gramática para falar inglês", "precisa gramática inglês", "falar inglês erros"], "Você não precisa dominar toda a gramática antes de falar, mas algum conhecimento de estruturas ajuda a organizar ideias e reduzir ambiguidades. O melhor é aprender um padrão e usá-lo em comunicação realista para seu nível.", [
    section("Aprenda estruturas ligadas a uma tarefa", ["Se quer se apresentar, pratique to be e perguntas simples. Para falar de rotina, estude simple present junto de horários e atividades."], ["I work on weekdays. — Trabalho durante a semana.", "Do you study English? — Você estuda inglês?"]),
    section("Alterne precisão e fluidez", ["Em um exercício, você pode focar em acertar uma estrutura. Em outro, tente manter a conversa sem interromper cada frase. As duas formas de prática têm valor."]),
    section("Use erros para escolher o próximo estudo", ["Se um erro se repete e atrapalha o sentido, revise a regra e refaça a tarefa. Não é necessário parar toda interação por cada pequeno deslize."]),
  ]),
  article("second-conditional-situacoes-hipoteticas", "Gramática essencial", "Second conditional: como falar de situações hipotéticas em inglês", "Forme hipóteses imaginárias ou pouco prováveis com if e would.", "If…", ["second conditional inglês", "if would", "hipóteses inglês"], "O second conditional é usado para imaginar uma situação presente ou futura considerada improvável ou hipotética e falar de seu possível resultado. A estrutura comum é if + simple past, would + verbo base.", [
    section("Condição imaginada e resultado", ["O simple past nessa estrutura não indica necessariamente passado real; ajuda a apresentar a hipótese como distante da realidade atual."], ["If I had more time, I would learn another language. — Se eu tivesse mais tempo, aprenderia outra língua."]),
    section("Were em situações hipotéticas", ["Em registros mais formais, were pode ser usado com todos os sujeitos em If I were…; na conversa, você também ouvirá was em alguns contextos."], ["If I were you, I’d ask for help. — Se eu fosse você, pediria ajuda."]),
    section("Não confunda com first conditional", ["Use first conditional para condições futuras vistas como possíveis; second conditional costuma apresentar cenário hipotético ou menos provável."]),
  ]),
  article("used-to-vs-simple-past", "Gramática essencial", "Used to ou simple past: como falar de hábitos antigos?", "Diferencie hábitos que mudaram de acontecimentos passados concluídos.", "↺", ["used to diferença simple past", "hábitos passado inglês", "used to exemplos"], "Use used to + verbo base para falar de hábitos ou estados que eram verdadeiros no passado e já não são, ou não são mais considerados atuais. O simple past pode narrar eventos ou hábitos passados sem destacar essa mudança.", [
    section("Used to destaca contraste com o presente", ["A expressão costuma sugerir que a situação mudou, embora o contexto determine a leitura."], ["I used to live in Recife. — Eu morava em Recife (agora moro em outro lugar).", "She used to play tennis. — Ela costumava jogar tênis."]),
    section("Simple past conta o que aconteceu", ["Use o passado simples para eventos específicos ou narrativas, sem necessariamente enfatizar um contraste atual."], ["I lived in Recife for two years. — Morei em Recife por dois anos.", "We played tennis yesterday. — Jogamos tênis ontem."]),
    section("Pergunta e negativa", ["Em formas com did, use use to na escrita padrão após o auxiliar."], ["Did you use to walk to school? — Você costumava ir a pé para a escola?", "I didn’t use to drink coffee. — Eu não costumava beber café."]),
  ]),
  article("perguntas-indiretas-educadas-ingles", "Gramática essencial", "Como fazer perguntas indiretas e mais educadas em inglês", "Use introduções como Could you tell me…? para perguntar com mais delicadeza.", "?", ["perguntas indiretas inglês", "perguntas educadas inglês", "could you tell me"], "Perguntas indiretas permitem pedir informação de maneira mais suave ou formal. Depois de expressões como Could you tell me…?, use a ordem de uma frase afirmativa dentro da pergunta indireta.", [
    section("Mude a ordem na pergunta embutida", ["A pergunta direta tem inversão; a parte indireta volta à ordem sujeito + verbo."], ["Where is the station? → Could you tell me where the station is?", "What time does it start? → Do you know what time it starts?"]),
    section("Use introduções apropriadas", ["Could you tell me…? e Do you know…? são opções comuns. A pergunta inteira ainda pode terminar com ponto de interrogação se for uma pergunta direta ao interlocutor."]),
    section("Evite repetir a inversão", ["Não mantenha a ordem interrogativa dentro da oração indireta."], ["Could you tell me where the station is? ✓", "Could you tell me where is the station? ✗"]),
  ], "6 min"),
  article("adjetivos-ed-ing-diferenca", "Gramática essencial", "Adjetivos terminados em -ed e -ing: bored ou boring?", "Entenda quem sente a emoção e o que a provoca nesses pares comuns.", "ed/ing", ["bored boring diferença", "adjetivos ed ing", "interested interesting"], "Muitos pares de adjetivos em -ed e -ing descrevem perspectivas diferentes: a forma em -ed costuma indicar como alguém se sente; a forma em -ing descreve algo ou alguém que provoca essa sensação.", [
    section("-ed: sentimento de quem vive a experiência", ["A forma em -ed geralmente descreve a reação de uma pessoa ou animal."], ["I’m bored. — Estou entediado/entediada.", "They were interested in the story. — Eles ficaram interessados na história."]),
    section("-ing: característica que provoca a reação", ["A forma em -ing descreve o efeito ou característica de algo."], ["The film is boring. — O filme é entediante.", "It was an interesting story. — Foi uma história interessante."]),
    section("Compare o sujeito e o efeito", ["Pergunte: quem sente a emoção? Ou o que a provoca? Essa distinção ajuda a escolher o adjetivo adequado."]),
  ]),
  article("cognatos-verdadeiros-ingles-portugues", "Vocabulário e uso", "Cognatos em inglês: palavras parecidas que ajudam a aprender", "Reconheça palavras com origem e significado próximos, conferindo sempre o contexto.", "≈", ["cognatos inglês português", "palavras parecidas inglês", "cognatos verdadeiros"], "Cognatos são palavras de línguas diferentes que compartilham origem e forma semelhante, muitas vezes com significado próximo. Eles podem facilitar a leitura, mas vale confirmar sentido, pronúncia e uso na frase.", [
    section("Use a semelhança como pista", ["Palavras como animal, hospital e important se parecem com equivalentes em português e podem ajudar a inferir um texto."], ["The hospital is near the park. — O hospital fica perto do parque."]),
    section("Confirme classe e combinação", ["Uma palavra cognata pode não ser usada exatamente da mesma forma. Veja se funciona como substantivo, adjetivo ou verbo e que outras palavras aparecem ao redor."]),
    section("Cuidado com falsos cognatos", ["Semelhança não garante significado igual. Verifique no contexto quando a tradução intuitiva parecer estranha ou mudar o sentido da frase."]),
  ]),
  article("conectores-para-escrever-ingles", "Writing", "Conectores em inglês: como ligar ideias em um texto", "Escolha conectores de adição, contraste, causa e sequência com clareza.", "↗", ["conectores inglês", "linking words", "conectar ideias inglês"], "Conectores ajudam a mostrar a relação entre ideias: adição, contraste, causa, resultado ou sequência. Escolha o conector pelo sentido, não para enfeitar cada frase.", [
    section("Adição e contraste", ["Use and ou also para acrescentar; but ou however para apresentar contraste. A pontuação pode variar conforme a posição do conector."], ["The course is short, but it is useful. — O curso é curto, mas é útil.", "The task is simple. However, it takes time. — A tarefa é simples. No entanto, leva tempo."]),
    section("Causa e resultado", ["Because apresenta uma razão; so pode apresentar um resultado em uma frase coordenada."], ["I stayed home because I was tired. — Fiquei em casa porque estava cansado.", "It was late, so we took a taxi. — Era tarde, então pegamos um táxi."]),
    section("Sequência e exemplo", ["First, then e finally organizam etapas; for example introduz uma ilustração. Evite usar conectores sem que haja relação lógica entre as ideias."]),
  ], "6 min"),
  article("soletrar-nome-email-ingles", "Inglês para situações práticas", "Como soletrar nomes, e-mails e confirmar números em inglês", "Peça para repetir ou soletrar dados importantes sem adivinhar letras e números.", "ABC", ["soletrar em inglês", "alfabeto inglês telefone", "confirmar números inglês"], "Ao informar nomes, e-mails ou números, soletrar e repetir os dados ajuda a reduzir erros. Confirme a informação em voz alta e peça esclarecimento quando o som de duas letras ou números for parecido.", [
    section("Peça para soletrar", ["Spell é soletrar. Use perguntas diretas e peça que a pessoa confirme a grafia."], ["Could you spell your last name, please? — Poderia soletrar seu sobrenome, por favor?", "That’s M-A-R-I-A, right? — É M-A-R-I-A, certo?"]),
    section("Confirme e-mails e números", ["Diga sinais e algarismos com clareza. Em e-mails, at representa @ e dot costuma indicar ponto."], ["Is that ‘b’ as in ‘book’ or ‘d’ as in ‘desk’? — É b de book ou d de desk?", "Could you repeat the phone number slowly? — Poderia repetir o telefone devagar?"]),
    section("Use uma confirmação final", ["Repita o dado completo e confirme antes de encerrar uma ligação, preencher um formulário ou enviar um documento importante."]),
  ], "5 min"),
];

const certificateGuides: Article[] = [
  article("certificado-cambridge-qual-exame-escolher", "Certificações de inglês", "Qual exame Cambridge escolher? A2 Key, B1 Preliminary, B2 First, C1 Advanced ou C2 Proficiency", "Compare as principais qualificações Cambridge por nível CEFR, objetivo e próximo passo — sem tratar um exame como solução universal.", "C", ["exames Cambridge qual escolher", "Cambridge A2 Key B1 Preliminary B2 First", "C1 Advanced C2 Proficiency", "certificado Cambridge inglês"], "As qualificações Cambridge English cobrem diferentes etapas do CEFR: A2 Key, B1 Preliminary, B2 First, C1 Advanced e C2 Proficiency. A escolha depende do nível que você consegue demonstrar hoje e de quem receberá o resultado. Antes de pagar, verifique no site oficial do exame e na instituição destinatária qual certificado, modalidade, nota e data são aceitos.", [
    section("Como os exames se relacionam aos níveis CEFR", ["Cambridge posiciona A2 Key em A2, B1 Preliminary em B1, B2 First em B2, C1 Advanced em C1 e C2 Proficiency em C2. Os nomes das qualificações indicam o nível-alvo; um resultado na Cambridge English Scale pode, conforme o exame e a faixa obtida, reconhecer desempenho em outro nível. Confirme a tabela atual na página oficial da qualificação."], ["A2 Key → A2", "B1 Preliminary → B1", "B2 First → B2", "C1 Advanced → C1", "C2 Proficiency → C2"], undefined, [{label:"Lista oficial de qualificações Cambridge",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"CEFR e Cambridge English Scale",url:"https://www.cambridgeenglish.org/exams-and-tests/cefr/"}]),
    section("Qual deles faz sentido para o seu objetivo?", ["Para documentar uma meta intermediária, selecione o exame alinhado ao nível que já consegue sustentar em leitura, escrita, escuta e fala. Para universidade, emprego ou imigração, não escolha apenas pelo nível: consulte a lista do destinatário. Requisitos podem especificar exame, versão, nota mínima por habilidade e prazo de validade da evidência."], undefined, ["Estudo geral ou marco pessoal: escolha o nível-alvo realista e confira o formato do exame.", "Universidade ou bolsa: procure a página de admissões do curso e registre notas totais e por habilidade exigidas.", "Trabalho ou imigração: consulte o órgão ou empregador responsável; regras variam por programa e podem mudar."]),
    section("O certificado Cambridge expira?", ["A Cambridge informa qualificações e resultados; não presuma que a regra de aceitação de uma instituição seja igual à política do emissor. A página de cada curso, universidade ou empregador é a referência para saber se aceita um certificado antigo ou pede evidência recente. Guarde o resultado e confirme a política diretamente com quem o avaliará." ]),
    section("Como comparar o nível com sua capacidade atual", ["O nível CEFR descreve competências linguísticas, não uma certificação automática. Use descritores para identificar o que consegue fazer, depois experimente tarefas no formato oficial. Um diagnóstico ou aula gratuita pode orientar a prática, mas não substitui uma prova oficial nem garante aprovação."], undefined, undefined, [{label:"Cambridge: qualificações e exames",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"B2 First",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/"},{label:"C1 Advanced",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/"},{label:"C2 Proficiency",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/proficiency/"},{label:"Quadro CEFR da Cambridge",url:"https://www.cambridgeenglish.org/exams-and-tests/cefr/"}])
  ], "8 min"),
  article("cambridge-b2-first-como-funciona", "Certificações de inglês", "B2 First (FCE): para que serve e como se preparar?", "Entenda o nível-alvo, o uso do B2 First e o que verificar antes de escolher a prova.", "B2", ["B2 First FCE para que serve", "exame Cambridge B2 First", "preparação B2 First", "nível B2 Cambridge"], "B2 First, antes conhecido pela sigla FCE, é uma qualificação Cambridge voltada ao nível B2 do CEFR. A Cambridge descreve a prova como evidência de que a pessoa pode viver ou trabalhar em ambiente anglófono ou estudar em inglês. Isso não significa aceitação automática em todo curso ou processo: cada destinatário publica seus próprios requisitos.", [
    section("O que o B2 First demonstra", ["A prova é orientada a tarefas de inglês de nível B2. A página oficial apresenta a qualificação e os componentes do exame; consulte-a para confirmar formato, versão digital ou em papel, duração, taxas e disponibilidade no centro escolhido, pois esses detalhes operacionais podem mudar."], undefined, undefined, [{label:"B2 First: página oficial",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/"},{label:"Formato e componentes oficiais",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/format/"}]),
    section("Como saber se B2 First é o exame adequado", ["Comece pelo requisito escrito da instituição: ela pede especificamente B2 First ou aceita outros testes? Existe nota mínima global e por habilidade? Aceita resultados de qualquer data? Se a resposta exigir um exame diferente ou recente, um certificado de nível compatível não necessariamente substitui a prova solicitada."], ["1. Copie o nome do teste e os mínimos exatamente como aparecem no requisito.", "2. Confirme prazo de validade e forma de envio diretamente com o destinatário.", "3. Escolha data de prova com margem para resultado, repetição ou envio documental."]),
    section("Como se preparar sem estudar só para macetes", ["Faça uma tarefa diagnóstica cronometrada para cada habilidade. Depois classifique erros por causa: vocabulário insuficiente, interpretação do enunciado, organização de texto, controle gramatical ou falta de tempo. Use provas de amostra e materiais oficiais para conhecer o formato, mas também mantenha prática ampla de leitura, escuta, produção oral e escrita."], undefined, ["Treine uma escrita por gênero e revise propósito, leitor, coesão e precisão.", "Na fala, grave respostas se desejar e avalie desenvolvimento, clareza e interação; não apenas velocidade.", "Refaça tarefas semelhantes após feedback e compare erros recorrentes."]),
    section("Perguntas frequentes", ["O B2 First é o mesmo que FCE? FCE é o nome antigo ainda usado informalmente; consulte o nome atual e a versão reconhecida pela instituição. O resultado vale para sempre? Não infira aceitação institucional a partir do nome: pergunte ao destinatário se há prazo. A prova garante admissão? Não; a instituição avalia todos os requisitos do processo."], undefined, undefined, [{label:"Página oficial B2 First",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/"},{label:"Resultados e Cambridge English Scale",url:"https://www.cambridgeenglish.org/exams-and-tests/cambridge-english-scale/"}])
  ], "7 min"),
  article("cambridge-c1-advanced-o-que-e", "Certificações de inglês", "C1 Advanced: o que é o CAE e quem costuma precisar dele?", "Veja o nível C1, o que a qualificação demonstra e como verificar requisitos de aceitação.", "C1", ["C1 Advanced o que é", "CAE Cambridge C1", "certificado C1 Cambridge", "exame avançado de inglês"], "C1 Advanced, anteriormente conhecido como CAE, é uma qualificação Cambridge no nível C1 do CEFR. A página oficial descreve usos acadêmicos e profissionais para pessoas que precisam de inglês de alto nível. Ela não transforma o certificado em requisito universal: a instituição, o empregador ou o órgão que recebe a candidatura define o que aceita.", [
    section("O que significa C1 neste exame", ["Na Cambridge English Scale, C1 Advanced tem pontuação-alvo indicada na página oficial. A Cambridge também pode reportar níveis conforme a faixa de desempenho do candidato. Leia a tabela oficial atual para interpretar resultado, nível reportado e certificado; não converta uma pontuação isolada em garantia de competência em todos os contextos."], undefined, undefined, [{label:"C1 Advanced: nível e escala",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/"},{label:"Cambridge English Scale",url:"https://www.cambridgeenglish.org/exams-and-tests/cambridge-english-scale/"}]),
    section("Para quem pode fazer sentido", ["Pode ser relevante quando uma universidade, empregador ou plano pessoal pede evidência de inglês avançado e aceita explicitamente C1 Advanced. Antes da inscrição, confira o curso/programa exato, notas totais e por componente, modalidade de prova, prazo de resultado e política para certificados antigos."], undefined, ["Procure o nome do exame na página de requisitos do destinatário.", "Registre se a exigência é C1 global, nota mínima ou desempenho por habilidade.", "Se o destinatário pede teste recente, pergunte se aceita resultado Cambridge de data anterior."]),
    section("Como estudar para C1 com consistência", ["Combine prática geral de C1 — leitura extensa, escuta de diferentes registros, escrita revisada e interação oral — com o formato oficial. Analise tarefas modelo para identificar rubricas e limitações de tempo. Faça simulados apenas quando puder revisar os resultados; repetir testes sem feedback pode repetir os mesmos erros."], ["Plano de 4 semanas: diagnóstico → prática focada → revisão de erros → simulado e reflexão.", "Em escrita: revise tese, estrutura, coesão, registro e precisão lexical.", "Em fala: desenvolva ideias, responda ao interlocutor e sustente afirmações com exemplos pertinentes."]),
    section("Dúvidas comuns sobre o CAE", ["CAE ainda é usado como nome? Sim, é uma designação histórica/informal; o nome atual é C1 Advanced. O certificado expira? A página de exame não deve ser tratada como política universal de admissão: confirme diretamente com quem recebe o documento. C1 Advanced é melhor que IELTS? Não há “melhor” universal; são instrumentos diferentes e o requisito do destinatário decide."], ["[Página oficial C1 Advanced](https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/)", "[Cambridge English Scale](https://www.cambridgeenglish.org/exams-and-tests/cambridge-english-scale/)", "[CEFR e Cambridge](https://www.cambridgeenglish.org/exams-and-tests/cefr/)"])
  ], "7 min"),
  article("ielts-ou-cambridge-qual-prova-escolher", "Certificações de inglês", "IELTS ou Cambridge: qual prova de inglês escolher?", "Compare finalidade, formato, prazo de uso do resultado e aceitação pelo destinatário.", "↔", ["IELTS ou Cambridge", "diferença IELTS Cambridge", "qual certificado inglês escolher", "validade IELTS Cambridge"], "IELTS e Cambridge English atendem a objetivos diferentes; a escolha mais segura é seguir o requisito da instituição que receberá o resultado. IELTS é reportado por bandas e costuma ser usado em processos que pedem um resultado recente. Cambridge oferece qualificações associadas a níveis CEFR específicos. Não decida só por reputação ou por uma tabela de equivalência genérica.", [
    section("Diferenças que ajudam na decisão", ["IELTS Academic e General Training têm finalidades e formatos próprios; verifique qual módulo o programa exige. IELTS recomenda considerar resultados como evidência de proficiência por até dois anos, mas instituições definem suas políticas. Cambridge B2 First, C1 Advanced e C2 Proficiency são qualificações associadas a níveis CEFR; a aceitação e a exigência de atualidade também dependem do destinatário."], ["IELTS: confira Academic/General Training, banda global, bandas por habilidade e data exigida.", "Cambridge: confira qualificação/nome atual, nível, resultado e notas mínimas pedidos.", "Em ambos: confirme o requisito na página da instituição antes de pagar a inscrição."]),
    section("Como escolher por objetivo", ["Para admissão, bolsa ou imigração, abra o requisito oficial e anote exame, versão, nota, validade, modalidade, prazo e forma de envio. Se duas opções forem aceitas, compare disponibilidade local, formato, custo atualizado, tempo de resultado e familiaridade com as tarefas. Consulte fontes oficiais para taxas e datas, pois variam por país e centro."], undefined, ["Se há prazo curto, priorize disponibilidade e tempo oficial de processamento.", "Se o resultado é para visto, confirme a lista de testes autorizados do programa específico.", "Se é meta pessoal, escolha o formato que melhor corresponde ao que deseja demonstrar."]),
    section("Validade: o ponto que costuma gerar confusão", ["IELTS recomenda uma janela de dois anos para interpretar resultados como evidência de capacidade atual, mas não é uma lei que determine a política de toda organização. Um certificado Cambridge não deve ser presumido aceito indefinidamente em todo processo: a universidade, empresa ou órgão pode pedir prova recente. Confirme sempre com o destinatário."], undefined, undefined, [{label:"IELTS: interpretação e validade recomendada",url:"https://ielts.org/organisations/ielts-for-organisations/understanding-ielts-scoring"},{label:"Cambridge: exames e qualificações",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"Cambridge C1 Advanced",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/"}]),
    section("Perguntas frequentes", ["IELTS equivale a um nível Cambridge? Há tabelas de comparação indicativas, mas uma instituição pode definir seus próprios cortes. Posso enviar qualquer exame? Só se o destinatário aceitar aquela versão. Preciso escolher o exame mais difícil? Não: escolha aquele que atende ao requisito e cujo formato você consegue preparar com evidência suficiente." ])
  ], "8 min"),
  article("ielts-academic-ou-general-training", "Certificações de inglês", "IELTS Academic ou General Training: qual módulo é o certo?", "Entenda a finalidade dos módulos IELTS e confirme o requisito antes de reservar a prova.", "I", ["IELTS Academic ou General Training", "diferença IELTS Academic General", "qual IELTS fazer", "IELTS para universidade imigração"], "IELTS tem módulos Academic e General Training. A escolha deve seguir o propósito e o requisito publicado pelo curso, órgão ou empregador: não existe um módulo universalmente correto para todas as candidaturas. Verifique as regras específicas antes de pagar ou marcar a prova.", [
    section("Quando o Academic pode ser solicitado", ["IELTS Academic avalia inglês em contextos ligados a estudo superior e, em alguns casos, registro profissional. A instituição define o módulo, a pontuação global e possíveis mínimos por habilidade. Não presuma que qualquer programa aceita General Training apenas porque a pontuação parece suficiente." ]),
    section("Quando o General Training pode ser solicitado", ["General Training é usado em alguns contextos de trabalho, formação e migração; as exigências dependem do país, do visto e do processo. Órgãos podem limitar quais testes, formatos ou versões aceitam. Consulte a página oficial do programa, não apenas recomendações de terceiros." ]),
    section("Checklist antes de reservar", ["Leia a fonte oficial da candidatura e confirme módulo, formato, centro, data, prazo de resultado e regra para resultados anteriores. Se a página não estiver clara, pergunte ao setor responsável por escrito. O mesmo IELTS pode ser adequado para um objetivo e inadequado para outro, mesmo que os níveis de inglês sejam comparáveis."], undefined, ["1. Nome do programa/curso e ano de candidatura.", "2. Academic ou General Training, incluindo modalidade autorizada.", "3. Banda global e mínimos de Listening, Reading, Writing e Speaking.", "4. Prazo de validade que o destinatário aplica."]),
    section("IELTS e validade do resultado", ["IELTS recomenda considerar resultados por até dois anos como evidência do nível atual; instituições mantêm a decisão de aceitar ou não um resultado em seu processo. Confirme a política da organização mesmo quando seu TRF ainda está disponível."], undefined, undefined, [{label:"IELTS: Understanding IELTS scoring",url:"https://ielts.org/organisations/ielts-for-organisations/understanding-ielts-scoring"},{label:"IELTS: Academic e General Training",url:"https://ielts.org/take-a-test/test-types"}])
  ], "6 min"),
  article("toefl-ibt-o-que-e-validade-e-aceitacao", "Certificações de inglês", "TOEFL iBT: o que é, para que serve e por quanto tempo vale?", "Entenda o uso acadêmico do TOEFL iBT, os resultados e como confirmar exigências institucionais.", "T", ["TOEFL iBT o que é", "validade TOEFL dois anos", "TOEFL para universidade", "TOEFL nota CEFR"], "TOEFL iBT é um teste de inglês usado por instituições em processos acadêmicos e outros contextos que aceitam seus resultados. Requisitos variam: confirme a versão, nota global, cortes por habilidade e prazo diretamente com a universidade ou órgão. A ETS informa que as pontuações TOEFL têm validade de dois anos a partir da data do teste.", [
    section("O que verificar no resultado", ["Consulte sua conta ETS para o boletim oficial, a escala de notas vigente e a opção de envio às instituições. A pontuação solicitada é definida pelo destinatário; não há uma nota única que garanta admissão. Confirme também a data em que o resultado precisa estar válido e recebido." ]),
    section("Como escolher TOEFL ou outro exame", ["Primeiro verifique se o programa aceita TOEFL iBT e qual versão/modalidade reconhece. Depois compare datas, processamento, custo vigente e formato de tarefas com outras alternativas aceitas. Uma comparação CEFR pode ajudar a interpretar nível, mas não substitui o corte definido pela instituição."], undefined, ["Confirme o código/nome do exame na página de admissões.", "Anote nota total e mínimos por seção.", "Planeje o teste com margem para relatório oficial ou nova tentativa."]),
    section("Validade e envio", ["A ETS afirma que as pontuações TOEFL são válidas por dois anos após a data do teste. Se o resultado ultrapassou esse prazo, verifique se ainda pode ser enviado e se o destinatário o aceita; não trate disponibilidade técnica ou uma comparação de nível como extensão da validade oficial."], undefined, undefined, [{label:"ETS: TOEFL iBT scores",url:"https://www.ets.org/toefl/test-takers/ibt/scores.html"},{label:"ETS: Understand your scores",url:"https://www.ets.org/toefl/test-takers/ibt/scores/understand-scores.html"}])
  ], "7 min"),
  article("pte-academic-o-que-e-validade", "Certificações de inglês", "PTE Academic: como funciona e quando é aceito?", "Veja o formato computadorizado, as quatro habilidades e os cuidados com validade e aceitação.", "P", ["PTE Academic como funciona", "validade PTE Academic", "PTE para universidade", "PTE Academic inglês"], "PTE Academic é um teste computadorizado de inglês que avalia speaking, writing, reading e listening em uma sessão. Pearson informa que a prova dura aproximadamente duas horas e atende a objetivos de estudo, trabalho e migração nos contextos em que o resultado é aceito. O destinatário, não o nome do teste, define se ele serve ao processo específico.", [
    section("Formato e habilidades", ["A página de Pearson descreve tarefas integradas e seções de Speaking & Writing, Reading e Listening. Consulte a página oficial antes de reservar porque duração, tarefas, disponibilidade de centro e serviços podem mudar. Conheça o formato usando os materiais oficiais atuais."], undefined, undefined, [{label:"PTE Academic: formato oficial",url:"https://www.pearsonpte.com/pte-academic/"}]),
    section("Validade do PTE Academic", ["Pearson informa validade de dois anos a partir da data da prova. Ainda assim, confira o prazo que a universidade, empregador ou autoridade aplica e se exige resultado recebido antes de uma data de corte. Uma pontuação dentro do prazo não garante aceitação se o programa não aceitar esse teste."], undefined, undefined, [{label:"PTE Academic: prazo e detalhes oficiais",url:"https://www.pearsonpte.com/pte-academic/"}]),
    section("Perguntas antes de pagar", ["Confirme se o destinatário aceita PTE Academic, qual nota global e por habilidade pede, se aceita a versão pretendida e como os resultados devem ser enviados. Compare valores apenas em páginas oficiais e na moeda/localidade aplicável; não use preços antigos de artigos de terceiros."], undefined, undefined, [{label:"PTE Academic: formato e validade",url:"https://www.pearsonpte.com/pte-academic/"},{label:"Cambridge: comparação CEFR para orientação",url:"https://www.cambridgeenglish.org/exams-and-tests/cefr/"}])
  ], "6 min"),
  article("duolingo-english-test-o-que-saber", "Certificações de inglês", "Duolingo English Test: o que é e o que conferir antes de fazer?", "Entenda o teste remoto e verifique a aceitação do programa antes de contar com o resultado.", "D", ["Duolingo English Test aceitação", "DET validade resultado", "teste inglês online universidade", "Duolingo English Test CEFR"], "Duolingo English Test (DET) é uma avaliação de inglês realizada online sob regras e supervisão definidas pelo emissor. A aceitação não é universal: cada universidade ou organização decide se recebe o DET, quais pontuações exige e em que datas. Antes de se preparar, consulte o site oficial da candidatura e a lista atualizada de instituições que aceitam o teste.", [
    section("Como confirmar se uma instituição aceita o DET", ["Procure o nome exato da universidade e do curso na página oficial de admissões. Verifique a pontuação global, subscores, prazo de validade, forma de envio e limitações para programas específicos. A aceitação geral de uma instituição não garante que cada faculdade, bolsa ou curso aceite o teste." ]),
    section("Validade do resultado", ["A política oficial pode mudar; consulte a página atual de resultados do DET e as exigências da organização destinatária antes de reservar. Não presuma que um score report disponível continuará aceito em um ciclo de candidatura futuro. Registre a data da prova e a data-limite publicada pelo programa."], undefined, undefined, [{label:"Duolingo English Test: resultados e pontuações",url:"https://englishtest.duolingo.com/scores"},{label:"Instituições que aceitam o DET",url:"https://englishtest.duolingo.com/institutions"}]),
    section("Preparação e condições do teste", ["Leia as regras técnicas, de identidade, ambiente e integridade acadêmica antes de pagar. Pratique as tarefas de amostra oficiais em um equipamento compatível. Um teste feito remotamente ainda exige cumprir os procedimentos de segurança do emissor e não elimina os requisitos acadêmicos da candidatura."], undefined, ["[Duolingo English Test: resultados e pontuações](https://englishtest.duolingo.com/scores)", "[Duolingo English Test: instituições](https://englishtest.duolingo.com/institutions)"])
  ], "6 min"),
  article("como-escolher-exame-certificacao-ingles", "Certificações de inglês", "Qual certificado de inglês fazer? Um checklist para escolher sem desperdiçar dinheiro", "Comece pelo requisito de quem receberá a nota, não por listas genéricas de “melhores provas”.", "✓", ["qual certificado inglês fazer", "melhor prova de inglês para universidade", "Cambridge IELTS TOEFL PTE", "validade certificado inglês"], "Não existe um único “melhor certificado de inglês” para todas as pessoas. IELTS, TOEFL iBT, PTE Academic, Duolingo English Test e Cambridge English podem atender a necessidades diferentes, mas o processo de admissão, visto, empregador ou órgão define quais testes reconhece. O primeiro passo é consultar esse requisito oficial.", [
    section("Checklist em cinco etapas", ["Use esta sequência para comparar provas com segurança."], undefined, ["Identifique quem receberá o resultado e o objetivo (curso, visto, trabalho ou meta pessoal).", "Confirme o teste e a versão autorizados para o programa e o ciclo atual.", "Anote pontuação global, mínimos por habilidade, CEFR se informado, validade e prazo de envio.", "Compare datas disponíveis, local/modalidade, tempo de processamento e custo atualizado em fontes oficiais.", "Escolha uma data que permita receber e, se necessário, refazer a prova antes do prazo."]),
    section("Comparação rápida sem equivalências simplistas", ["Cambridge oferece qualificações como B2 First, C1 Advanced e C2 Proficiency associadas a níveis CEFR. IELTS reporta bandas e recomenda interpretar resultados por até dois anos, enquanto a instituição define sua política. TOEFL iBT e PTE Academic informam validade de dois anos para resultados. Para Duolingo English Test, confirme a validade e a aceitação atuais nas páginas do emissor e do destinatário. Esses sistemas não são intercambiáveis automaticamente."], undefined, undefined, [{label:"Cambridge English",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"IELTS scoring",url:"https://ielts.org/organisations/ielts-for-organisations/understanding-ielts-scoring"},{label:"TOEFL iBT scores",url:"https://www.ets.org/toefl/test-takers/ibt/scores.html"},{label:"PTE Academic",url:"https://www.pearsonpte.com/pte-academic/"},{label:"Duolingo English Test",url:"https://englishtest.duolingo.com/scores"}]),
    section("O curso prepara para esses certificados?", ["Uma trilha CEFR e atividades de inglês podem desenvolver competências gerais, mas não equivalem a um exame oficial nem garantem pontuação. Use uma aula de diagnóstico para escolher o nível de estudo e acrescente prática específica do exame aceito pelo seu destinatário."], ["[Explore a trilha de inglês A1–C2](/curso)", "[Faça o diagnóstico orientativo](/diagnostico)"])
  ], "8 min"),
];

const existingArticleSlugs = new Set(articleDrafts.map((item) => item.slug));
const duplicateCertificateSlugs = certificateGuides.filter((item) => existingArticleSlugs.has(item.slug));
if (duplicateCertificateSlugs.length) throw new Error(`Duplicate article slug: ${duplicateCertificateSlugs.map((item) => item.slug).join(", ")}`);

export const articles: Article[] = [...articleDrafts, ...certificateGuides];

